"use client";

import { Suspense, useEffect, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { toast } from "sonner";
import { createClient } from "@/lib/supabase-browser";
import { usePhoneInput } from "@/hooks/usePhoneInput";
import { useOTPInput } from "@/hooks/useOTPInput";
import { OTP_LENGTH, PHONE_DIGIT_LENGTH } from "@/lib/auth-constants";
import { clientLogger } from "@/lib/client-logger";
import {
  handleSendOTP as sendOTPHandler,
  handleVerifyOTP as verifyOTPHandler,
} from "@/lib/auth-handlers";
import { AuthCard } from "@/components/auth/AuthCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { joinClass, previewClass } from "@/app/actions/student";

// ========================================
// STEP 1: AUTH SELECTION
// ========================================
function AuthSelectionStep({
  onPhoneAuth,
  onAnonymousAuth,
}: {
  onPhoneAuth: () => void;
  onAnonymousAuth: () => void;
}) {
  return (
    <AuthCard
      title="Join Class"
      description="Choose how you'd like to continue"
    >
      <div className="space-y-4">
        <div className="bg-surface/50 p-4 rounded-lg border border-border">
          <p className="text-sm text-text-secondary mb-4">
            You need to sign in first to join a class. Choose one of the options
            below:
          </p>
        </div>

        <Button
          onClick={onPhoneAuth}
          className="w-full h-14 text-base text-[17px] shadow-[var(--shadow-primary)] hover:shadow-[var(--shadow-primary-hover)] hover:-translate-y-0.5 transition-all"
          variant="default"
        >
          <span className="text-xl mr-2">📱</span>
          Continue with Phone (OTP)
        </Button>

        <Button
          onClick={onAnonymousAuth}
          className="w-full h-14 text-base text-[17px] border-2 hover:border-primary hover:shadow-[var(--shadow-primary-sm)] hover:-translate-y-0.5 transition-all"
          variant="outline"
        >
          <span className="text-xl mr-2">👤</span>
          Continue as Guest
        </Button>

        <div className="bg-cyan-lightest border-l-4 border-cyan p-3 rounded-xl">
          <p className="text-xs text-cyan-darkest">
            <strong>💡 Guest Access:</strong> You can join as a guest and
            upgrade your account later by adding a phone number or email.
          </p>
        </div>

        <div className="text-center pt-2">
          <a
            href="/student/start"
            className="text-sm text-primary hover:underline"
          >
            Already have an account with email? Sign in here
          </a>
        </div>
      </div>
    </AuthCard>
  );
}

// ========================================
// STEP 2: PHONE OTP SIGN-IN
// ========================================
function PhoneOTPStep({
  onComplete,
  onBack,
  loading,
}: {
  onComplete: () => void;
  onBack: () => void;
  loading: boolean;
}) {
  const supabase = createClient();
  const [step, setStep] = useState<"phone" | "verify">("phone");
  const [stepLoading, setStepLoading] = useState(false);
  const phoneInput = usePhoneInput();
  const otpInput = useOTPInput();

  async function handleSendOTPClick(e: React.FormEvent) {
    e.preventDefault();
    setStepLoading(true);

    try {
      const result = await sendOTPHandler(
        supabase,
        phoneInput.fullValue,
        "phone",
      );

      if (!result.success) {
        toast.error(result.error || "Failed to send OTP");
      } else {
        toast.success("OTP sent to your phone!");
        setStep("verify");
      }
    } catch (error) {
      clientLogger.error(
        "[JoinClass] Failed to send OTP",
        error instanceof Error ? error : { error },
      );
      toast.error("Failed to send OTP");
    } finally {
      setStepLoading(false);
    }
  }

  async function handleVerifyOTPClick(e: React.FormEvent) {
    e.preventDefault();
    setStepLoading(true);

    try {
      const result = await verifyOTPHandler(
        supabase,
        { phone: phoneInput.fullValue },
        otpInput.value,
        "sms",
      );

      if (!result.success) {
        toast.error(result.error || "Failed to verify OTP");
      } else {
        toast.success("Phone verified! 🎉");
        onComplete();
      }
    } catch (error) {
      clientLogger.error(
        "[JoinClass] Failed to verify OTP",
        error instanceof Error ? error : { error },
      );
      toast.error("Failed to verify OTP");
    } finally {
      setStepLoading(false);
    }
  }

  if (step === "verify") {
    return (
      <AuthCard
        title="Verify OTP"
        description={`Enter the 6-digit code sent to ${phoneInput.fullValue}`}
      >
        <form onSubmit={handleVerifyOTPClick} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="otp">OTP Code</Label>
            <Input
              id="otp"
              type="text"
              placeholder="123456"
              value={otpInput.value}
              onChange={(e) => otpInput.onChange(e.target.value)}
              required
              disabled={stepLoading || loading}
              maxLength={OTP_LENGTH}
              className="text-center text-2xl font-mono tracking-widest"
            />
            <p className="text-xs text-text-secondary">
              Enter the 6-digit code sent to your phone
            </p>
          </div>

          <Button
            type="submit"
            className="w-full text-[17px] shadow-[var(--shadow-primary)] hover:shadow-[var(--shadow-primary-hover)] hover:-translate-y-0.5"
            disabled={
              stepLoading || loading || otpInput.value.length !== OTP_LENGTH
            }
            loading={stepLoading || loading}
          >
            Verify & Continue
            <span className="ml-2">→</span>
          </Button>

          <div className="text-center space-y-2">
            <button
              type="button"
              onClick={handleSendOTPClick}
              className="text-sm text-primary hover:text-primary-dark hover:underline block w-full"
              disabled={stepLoading || loading}
            >
              Resend OTP
            </button>
            <button
              type="button"
              onClick={() => setStep("phone")}
              className="text-sm text-primary hover:underline block w-full"
              disabled={stepLoading || loading}
            >
              Change phone number
            </button>
            <button
              type="button"
              onClick={onBack}
              className="text-sm text-text-secondary hover:underline block w-full"
              disabled={stepLoading || loading}
            >
              Back to options
            </button>
          </div>
        </form>
      </AuthCard>
    );
  }

  return (
    <AuthCard
      title="Phone Sign-in"
      description="Enter your phone number to receive an OTP"
    >
      <form onSubmit={handleSendOTPClick} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="phone">Phone Number</Label>
          <div className="flex items-center border border-input rounded-md">
            <span className="px-3 text-text-secondary font-medium bg-muted">
              +91
            </span>
            <Input
              id="phone"
              type="tel"
              placeholder="9876543210"
              value={phoneInput.displayValue}
              onChange={(e) => phoneInput.onChange(e.target.value)}
              required
              disabled={stepLoading || loading}
              className="border-0 flex-1"
              maxLength={12}
            />
          </div>
          <p className="text-xs text-text-secondary">
            Enter your 10-digit phone number
          </p>
        </div>

        <div className="bg-cyan-lightest border-l-4 border-cyan p-3 rounded-xl">
          <p className="text-xs text-cyan-darkest">
            <strong>📱 SMS Verification:</strong> You&apos;ll receive a 6-digit
            code via SMS. Standard rates may apply.
          </p>
        </div>

        <Button
          type="submit"
          className="w-full text-[17px] shadow-[var(--shadow-primary)] hover:shadow-[var(--shadow-primary-hover)] hover:-translate-y-0.5"
          disabled={
            stepLoading ||
            loading ||
            phoneInput.displayValue.length < PHONE_DIGIT_LENGTH
          }
          loading={stepLoading || loading}
        >
          Send OTP
          <span className="ml-2">→</span>
        </Button>

        <div className="text-center">
          <button
            type="button"
            onClick={onBack}
            className="text-sm text-text-secondary hover:underline block w-full"
            disabled={stepLoading || loading}
          >
            Back to options
          </button>
        </div>
      </form>
    </AuthCard>
  );
}

// ========================================
// CLASS PREVIEW INTERFACE
// ========================================
interface ClassPreviewData {
  className: string;
  teacherName: string;
  subject: string | null;
  studentCount: number;
}

// ========================================
// STEP 3: JOIN CLASS FORM (WITH PREVIEW)
// ========================================
function JoinClassForm({
  initialCode,
  initialPin,
}: {
  initialCode?: string;
  initialPin?: string;
}) {
  const router = useRouter();
  const [classCode, setClassCode] = useState(initialCode || "");
  const [pin, setPin] = useState(initialPin || "");
  const [loading, setLoading] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [preview, setPreview] = useState<ClassPreviewData | null>(null);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [showConfirm, setShowConfirm] = useState(false);

  // Preview class when code is complete (6 characters)
  async function handlePreviewClass() {
    if (classCode.length !== 6) return;

    setPreviewLoading(true);
    setPreviewError(null);
    setPreview(null);

    try {
      const result = await previewClass(classCode.toUpperCase().trim());

      if (result.success && result.data) {
        setPreview(result.data);
      } else {
        setPreviewError(result.error || "Class not found");
      }
    } catch (error) {
      clientLogger.error(
        "[JoinClass] Failed to preview class",
        error instanceof Error ? error : { error },
      );
      setPreviewError("Failed to lookup class");
    } finally {
      setPreviewLoading(false);
    }
  }

  // Auto-preview when code changes and becomes complete
  useEffect(() => {
    if (classCode.length === 6) {
      handlePreviewClass();
    } else {
      setPreview(null);
      setPreviewError(null);
      setShowConfirm(false);
    }
  }, [classCode]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    // If we have a preview but haven't confirmed yet, show confirmation
    if (preview && !showConfirm) {
      setShowConfirm(true);
      return;
    }

    setLoading(true);

    try {
      const result = await joinClass({
        classCode: classCode.toUpperCase().trim(),
        pin: pin.trim(),
      });

      if (result.success) {
        toast.success("Successfully joined class!");
        router.push("/app/student/classes");
      } else {
        toast.error(result.error || "Failed to join class");
      }
    } catch (error) {
      clientLogger.error(
        "[JoinClass] Failed to join class",
        error instanceof Error ? error : { error },
      );
      toast.error("An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  }

  return (
    <AuthCard
      title="Join Class"
      description="Enter the class code and PIN provided by your teacher"
    >
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="class-code">Class Code</Label>
          <Input
            id="class-code"
            type="text"
            placeholder="A3F7E2"
            value={classCode}
            onChange={(e) => {
              setClassCode(e.target.value.toUpperCase());
              setShowConfirm(false);
            }}
            required
            disabled={loading}
            maxLength={6}
            className="uppercase font-mono text-center text-xl tracking-widest"
          />
          <p className="text-xs text-text-secondary">
            6-character code provided by your teacher
          </p>
        </div>

        {/* Class Preview Section */}
        {previewLoading && (
          <div className="bg-surface border border-border rounded-lg p-4">
            <div className="flex items-center gap-2">
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-primary"></div>
              <span className="text-sm text-text-secondary">
                Looking up class...
              </span>
            </div>
          </div>
        )}

        {previewError && (
          <div className="bg-error-light border-l-4 border-error p-3 rounded">
            <p className="text-sm text-error-dark">{previewError}</p>
          </div>
        )}

        {preview && (
          <div className="bg-success-light border border-success/30 rounded-lg p-4 space-y-2">
            <div className="flex items-center gap-2 mb-2">
              <span className="text-success text-lg">✓</span>
              <span className="font-medium text-success-dark">
                Class Found!
              </span>
            </div>
            <div className="space-y-1 text-sm">
              <div className="flex justify-between">
                <span className="text-text-secondary">Class Name:</span>
                <span className="font-medium text-text-primary">
                  {preview.className}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-text-secondary">Teacher:</span>
                <span className="font-medium text-text-primary">
                  {preview.teacherName}
                </span>
              </div>
              {preview.subject && (
                <div className="flex justify-between">
                  <span className="text-text-secondary">Subject:</span>
                  <span className="font-medium text-text-primary">
                    {preview.subject}
                  </span>
                </div>
              )}
              <div className="flex justify-between">
                <span className="text-text-secondary">Students:</span>
                <span className="font-medium text-text-primary">
                  {preview.studentCount} enrolled
                </span>
              </div>
            </div>
          </div>
        )}

        <div className="space-y-2">
          <Label htmlFor="pin">Class PIN</Label>
          <Input
            id="pin"
            type="password"
            placeholder="••••"
            value={pin}
            onChange={(e) => {
              setPin(e.target.value.replace(/\D/g, "").slice(0, 4));
              setShowConfirm(false);
            }}
            required
            disabled={loading}
            maxLength={4}
            className="text-center text-2xl font-mono tracking-widest"
          />
          <p className="text-xs text-text-secondary">
            4-digit PIN provided by your teacher
          </p>
        </div>

        {/* Confirmation Message */}
        {showConfirm && preview && (
          <div className="bg-primary/10 border border-primary/30 rounded-lg p-3">
            <p className="text-sm text-primary-dark text-center">
              Ready to join <strong>{preview.className}</strong> with{" "}
              {preview.teacherName}?
            </p>
          </div>
        )}

        <div className="bg-info-light border-l-4 border-info p-3 rounded">
          <p className="text-xs text-info-dark">
            <strong>Note:</strong> Your roll number from your profile will be
            used to identify you in the class roster.
          </p>
        </div>

        <Button
          type="submit"
          className="w-full text-[17px] shadow-[var(--shadow-primary)] hover:shadow-[var(--shadow-primary-hover)] hover:-translate-y-0.5"
          disabled={
            loading ||
            !classCode ||
            classCode.length !== 6 ||
            pin.length !== 4 ||
            !preview
          }
          loading={loading}
        >
          {showConfirm ? "Confirm & Join Class" : "Join Class"}
          <span className="ml-2">→</span>
        </Button>
      </form>
    </AuthCard>
  );
}

// ========================================
// MAIN COMPONENT
// ========================================
function JoinPageContent() {
  const supabase = createClient();
  const searchParams = useSearchParams();
  const router = useRouter();

  const codeFromUrl = searchParams.get("code");
  const pinFromUrl = searchParams.get("pin");
  const viaInvite = searchParams.get("via") === "invite";

  const [authState, setAuthState] = useState<
    "loading" | "unauthenticated" | "authenticated"
  >("loading");
  const [authMethod, setAuthMethod] = useState<
    "selection" | "phone" | "complete"
  >("selection");
  const [loading, setLoading] = useState(false);

  // Check auth status on mount
  useEffect(() => {
    async function checkAuth() {
      const {
        data: { session },
      } = await supabase.auth.getSession();

      if (session) {
        setAuthState("authenticated");
        setAuthMethod("complete");
      } else {
        setAuthState("unauthenticated");

        // If not via invite link, redirect to student start page
        if (!viaInvite && !codeFromUrl) {
          router.push("/student/start");
        }
      }
    }

    checkAuth();
  }, [supabase, viaInvite, codeFromUrl]);

  // Handle anonymous sign-in
  async function handleAnonymousAuth() {
    setLoading(true);
    try {
      const { error } = await supabase.auth.signInAnonymously();

      if (error) {
        toast.error(error.message);
      } else {
        toast.success("Signed in as guest!");
        setAuthMethod("complete");
        setAuthState("authenticated");
      }
    } catch (error) {
      clientLogger.error(
        "[JoinClass] Failed to sign in as guest",
        error instanceof Error ? error : { error },
      );
      toast.error("Failed to sign in as guest");
    } finally {
      setLoading(false);
    }
  }

  // Loading state
  if (authState === "loading") {
    return (
      <AuthCard title="Join Class" description="Loading...">
        <div className="flex justify-center py-8">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
        </div>
      </AuthCard>
    );
  }

  // Already authenticated - show join form
  if (authState === "authenticated" && authMethod === "complete") {
    return (
      <JoinClassForm
        initialCode={codeFromUrl || undefined}
        initialPin={pinFromUrl || undefined}
      />
    );
  }

  // Not authenticated - show auth options
  if (authMethod === "selection") {
    return (
      <AuthSelectionStep
        onPhoneAuth={() => setAuthMethod("phone")}
        onAnonymousAuth={handleAnonymousAuth}
      />
    );
  }

  // Phone OTP flow
  if (authMethod === "phone") {
    return (
      <PhoneOTPStep
        onComplete={() => {
          setAuthMethod("complete");
          setAuthState("authenticated");
        }}
        onBack={() => setAuthMethod("selection")}
        loading={loading}
      />
    );
  }

  // Fallback
  return (
    <JoinClassForm
      initialCode={codeFromUrl || undefined}
      initialPin={pinFromUrl || undefined}
    />
  );
}

export default function JoinClassPage() {
  return (
    <Suspense
      fallback={
        <AuthCard title="Join Class" description="Loading...">
          <div className="flex justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          </div>
        </AuthCard>
      }
    >
      <JoinPageContent />
    </Suspense>
  );
}

"use client";

import { Suspense, useEffect, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { toast } from "sonner";
import { createClient } from "@/lib/supabase-browser";
import { resetPasswordWithOtp } from "@/app/actions/auth";
import { useOTPInput } from "@/hooks/useOTPInput";
import { validateEmail, validatePasswordMatch } from "@/lib/validation-utils";
import { getPasswordValidationError } from "@/lib/password-utils";
import { OTP_LENGTH } from "@/lib/auth-constants";
import { AuthCard } from "@/components/auth/AuthCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { authLogger } from "@/lib/auth-logger";

function ResetPasswordContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const supabase = createClient();

  // Get email from URL param (set by password reset flow)
  const emailFromUrl = searchParams.get("email") || "";

  // Form state
  const [email, setEmail] = useState(emailFromUrl);
  const [otp, setOtp] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Initialize OTP input hook
  const otpInput = useOTPInput(otp);

  // Check if already authenticated - redirect to dashboard
  useEffect(() => {
    async function checkAuth() {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      if (session) {
        router.push("/app/dashboard");
      }
    }
    checkAuth();
  }, [supabase, router]);

  // Handle OTP input change (max 6 digits)
  const handleOtpChange = (value: string) => {
    const cleanValue = value.replace(/\D/g, "").slice(0, OTP_LENGTH);
    setOtp(cleanValue);
  };

  // Handle form submission
  async function handleResetPassword(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      // Validation
      if (!email.trim()) {
        setError("Email is required");
        setIsLoading(false);
        return;
      }

      if (otp.length !== OTP_LENGTH) {
        setError(`Verification code must be ${OTP_LENGTH} digits`);
        setIsLoading(false);
        return;
      }

      if (!newPassword) {
        setError("Password is required");
        setIsLoading(false);
        return;
      }

      if (newPassword !== confirmPassword) {
        setError("Passwords do not match");
        setIsLoading(false);
        return;
      }

      // Validate email format
      const emailValidation = validateEmail(email);
      if (!emailValidation.valid) {
        setError(emailValidation.error || "Invalid email");
        setIsLoading(false);
        return;
      }

      // Validate password (min 8 chars, max 64 chars, no complexity rules)
      const passwordError = getPasswordValidationError(newPassword);
      if (passwordError) {
        setError(passwordError);
        setIsLoading(false);
        return;
      }

      // Validate password match
      const matchValidation = validatePasswordMatch(
        newPassword,
        confirmPassword,
      );
      if (!matchValidation.valid) {
        setError(matchValidation.error || "Passwords do not match");
        setIsLoading(false);
        return;
      }

      authLogger.debug("[ResetPassword] Attempting password reset", {
        email: email.substring(0, 5) + "...",
      });

      // Call server action to reset password with OTP
      const result = await resetPasswordWithOtp(email.trim(), otp, newPassword);

      if (result.success) {
        authLogger.success("[ResetPassword] Password reset successful");
        toast.success(
          "Password reset successfully! Please log in with your new password.",
        );

        // Redirect to student login or check role
        setTimeout(() => {
          router.push("/student/start");
        }, 2000);
      } else {
        authLogger.error("[ResetPassword] Password reset failed", {
          error: result.error,
        });
        setError(result.error || "Failed to reset password");
        toast.error(
          result.error || "Failed to reset password. Please try again.",
        );
      }
    } catch (err) {
      authLogger.error("[ResetPassword] Unexpected error", err);
      const errorMsg =
        err instanceof Error ? err.message : "An unexpected error occurred";
      setError(errorMsg);
      toast.error(errorMsg);
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 px-4 py-8">
      <AuthCard title="Reset Password">
        <form onSubmit={handleResetPassword} className="space-y-4">
          {/* Email Field */}
          <div className="space-y-2">
            <Label htmlFor="email" className="text-sm font-medium">
              Email Address
            </Label>
            <Input
              id="email"
              type="email"
              placeholder="your@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              disabled={isLoading || !!emailFromUrl}
              className="w-full"
            />
            <p className="text-xs text-gray-600">
              We sent a verification code to this email address
            </p>
          </div>

          {/* OTP Field */}
          <div className="space-y-2">
            <Label htmlFor="otp" className="text-sm font-medium">
              Verification Code
            </Label>
            <Input
              id="otp"
              type="text"
              placeholder="000000"
              value={otp}
              onChange={(e) => handleOtpChange(e.target.value)}
              disabled={isLoading}
              maxLength={OTP_LENGTH}
              className="w-full text-center text-2xl tracking-widest font-mono"
            />
            <p className="text-xs text-gray-600">
              Enter the 6-digit code from your email
            </p>
          </div>

          {/* New Password Field */}
          <div className="space-y-2">
            <Label htmlFor="newPassword" className="text-sm font-medium">
              New Password
            </Label>
            <Input
              id="newPassword"
              type="password"
              placeholder="Enter new password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              disabled={isLoading}
              className="w-full"
            />
            <p className="text-xs text-gray-600">Minimum 8 characters</p>
          </div>

          {/* Confirm Password Field */}
          <div className="space-y-2">
            <Label htmlFor="confirmPassword" className="text-sm font-medium">
              Confirm Password
            </Label>
            <Input
              id="confirmPassword"
              type="password"
              placeholder="Confirm your password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              disabled={isLoading}
              className="w-full"
            />
          </div>

          {/* Error Message */}
          {error && (
            <div className="p-3 bg-red-50 border border-red-200 rounded-md">
              <p className="text-sm text-red-700">{error}</p>
            </div>
          )}

          {/* Submit Button */}
          <Button
            type="submit"
            disabled={
              isLoading ||
              !email ||
              otp.length !== OTP_LENGTH ||
              !newPassword ||
              !confirmPassword
            }
            className="w-full mt-6"
          >
            {isLoading ? "Resetting Password..." : "Reset Password"}
          </Button>

          {/* Back to Login Link */}
          <div className="text-center">
            <p className="text-sm text-gray-600">
              Remember your password?{" "}
              <button
                type="button"
                onClick={() => router.push("/student/start")}
                className="text-blue-600 hover:underline font-medium"
              >
                Sign in here
              </button>
            </p>
          </div>
        </form>
      </AuthCard>
    </div>
  );
}

