/**
 * Type definitions for Supabase responses
 *
 * Note: Some interfaces include `[key: string]: unknown` to allow for additional fields
 * from Supabase responses. This is necessary because:
 * 1. Supabase may include extra metadata fields depending on the select() clause
 * 2. User-defined custom fields may be present in raw_user_meta_data
 * 3. Future schema extensions may add new fields
 *
 * When accessing these interfaces, always validate known required fields first.
 */

/**
 * User object from auth.users joined queries
 *
 * Guaranteed fields: id
 * Optional fields: email, raw_user_meta_data
 * Note: Not all fields are always available depending on the select clause used
 */
interface AuthUser {
  id: string;
  email?: string;
  raw_user_meta_data?: {
    full_name?: string;
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

/**
 * Get assessment results for students in a teacher's class
 * Teachers can view aggregate and individual student results
 */
export interface StudentAssessmentResult {
  studentId: string;
  studentName: string;
  rollNumber: string | null;
  sessionsCompleted: number;
  averageScore: number | null;
  lastAssessmentDate: string | null;
  totalQuestions: number;
  correctAnswers: number;
}

export interface ClassAssessmentResults {
  classId: string;
  className: string;
  totalStudents: number;
  studentsWithAssessments: number;
  classAverageScore: number | null;
  results: StudentAssessmentResult[];
}

/**
 * Type guard to safely validate student profile structure from Supabase
 */
function isValidStudentProfile(
  data: unknown,
): data is { name: string; roll_number: string | null } {
  if (typeof data !== "object" || data === null) {
    return false;
  }
  const obj = data as Record<string, unknown>;
  return (
    typeof obj.name === "string" &&
    (obj.roll_number === null || typeof obj.roll_number === "string")
  );
}

/**
 * Helper: Build lookup maps for sessions and responses
 */
function buildLookupMaps(
  allSessions: Array<{
    id: string;
    user_id: string;
    submitted_at: string;
  }> | null,
  allResponses: Array<{ session_id: string; is_correct: boolean }> | null,
): {
  sessionsByStudent: Map<string, Array<{ id: string; submitted_at: string }>>;
  responsesBySession: Map<string, Array<{ is_correct: boolean }>>;
} {
  const sessionsByStudent = new Map<
    string,
    Array<{ id: string; submitted_at: string }>
  >();
  const responsesBySession = new Map<string, Array<{ is_correct: boolean }>>();

  allSessions?.forEach((session) => {
    if (!sessionsByStudent.has(session.user_id)) {
      sessionsByStudent.set(session.user_id, []);
    }
    const studentSessions = sessionsByStudent.get(session.user_id);
    if (studentSessions) {
      studentSessions.push({
        id: session.id,
        submitted_at: session.submitted_at,
      });
    }
  });

  allResponses?.forEach((response) => {
    if (!responsesBySession.has(response.session_id)) {
      responsesBySession.set(response.session_id, []);
    }
    const sessionResponses = responsesBySession.get(response.session_id);
    if (sessionResponses) {
      sessionResponses.push({
        is_correct: response.is_correct,
      });
    }
  });

  return { sessionsByStudent, responsesBySession };
}

/**
 * Helper: Calculate student assessment statistics
 */
function calculateStudentStats(
  sessions: Array<{ id: string; submitted_at: string }>,
  responsesBySession: Map<string, Array<{ is_correct: boolean }>>,
): {
  sessionsCompleted: number;
  averageScore: number | null;
  lastAssessmentDate: string | null;
  totalQuestions: number;
  correctAnswers: number;
} {
  const sessionsCompleted = sessions.length;

  if (sessions.length === 0) {
    return {
      sessionsCompleted: 0,
      averageScore: null,
      lastAssessmentDate: null,
      totalQuestions: 0,
      correctAnswers: 0,
    };
  }

  sessions.sort(
    (a, b) =>
      new Date(b.submitted_at).getTime() - new Date(a.submitted_at).getTime(),
  );
  const lastAssessmentDate = sessions[0].submitted_at;

  let totalQuestions = 0;
  let correctAnswers = 0;

  for (const session of sessions) {
    const responses = responsesBySession.get(session.id) || [];
    totalQuestions += responses.length;
    correctAnswers += responses.filter((r) => r.is_correct).length;
  }

  const averageScore =
    totalQuestions > 0
      ? Math.round((correctAnswers / totalQuestions) * 100)
      : null;

  return {
    sessionsCompleted,
    averageScore,
    lastAssessmentDate,
    totalQuestions,
    correctAnswers,
  };
}

/**
 * Helper: Process student results from enrollments
 */
function processStudentResults(
  enrollments: Array<{
    student_id: string;
    student_profiles: { name: string; roll_number: string | null } | null;
  }> | null,
  sessionsByStudent: Map<string, Array<{ id: string; submitted_at: string }>>,
  responsesBySession: Map<string, Array<{ is_correct: boolean }>>,
): StudentAssessmentResult[] {
  const studentResults: StudentAssessmentResult[] = [];

  for (const enrollment of enrollments || []) {
    if (!isValidStudentProfile(enrollment.student_profiles)) {
      authLogger.warn(
        "[getClassAssessmentResults] Invalid student profile structure",
        {
          enrollment_id: enrollment.student_id,
        },
      );
      continue;
    }

    // isValidStudentProfile already ensures student_profiles is not null
    const studentProfile = enrollment.student_profiles;
    const sessions = sessionsByStudent.get(enrollment.student_id) || [];
    const stats = calculateStudentStats(sessions, responsesBySession);

    studentResults.push({
      studentId: enrollment.student_id,
      studentName: studentProfile.name,
      rollNumber: studentProfile.roll_number || null,
      sessionsCompleted: stats.sessionsCompleted,
      averageScore: stats.averageScore,
      lastAssessmentDate: stats.lastAssessmentDate,
      totalQuestions: stats.totalQuestions,
      correctAnswers: stats.correctAnswers,
    });
  }

  return studentResults;
}

/**
 * Get class assessment results (refactored to reduce cognitive complexity)
 * CRITICAL FIX: Reduced complexity from 21 to <15 by extracting helper functions
 */
export async function getClassAssessmentResults(classId: string): Promise<{
  success: boolean;
  data?: ClassAssessmentResults;
  error?: string;
}> {
  try {
    // Validate input
    let validatedClassId;
    try {
      validatedClassId = ClassIdSchema.parse(classId);
    } catch (error) {
      const zodError = handleZodError(error);
      return { success: zodError.success, error: zodError.error };
    }

    // SECURITY: Verify caller is authenticated and owns this class
    const auth = await verifyClassOwnership(
      "getClassAssessmentResults",
      validatedClassId,
    );
    if (!auth.authorized) {
      return auth.error;
    }

    const supabase = await createClient();

    // SECURITY FIX #4 EXTENSION: Re-verify class ownership before analytics queries
    // Prevents TOCTOU vulnerability if class is deleted/transferred after initial check
    const { data: classData, error: classDataError } = await supabase
      .from("classes")
      .select("id, teacher_id, name")
      .eq("id", validatedClassId)
      .maybeSingle();

    if (classDataError || !classData || classData.teacher_id !== auth.user.id) {
      authLogger.warn(
        "[getClassAssessmentResults] Access denied: Class no longer owned by user",
        {
          userId: auth.user.id,
          classId: validatedClassId,
        },
      );
      return { success: false, error: "You do not own this class" };
    }

    // Get all enrolled students
    const { data: enrollments, error: enrollmentError } = await supabase
      .from("enrollments")
      .select(
        `
        student_id,
        student_profiles!inner (
          name,
          roll_number
        )
      `,
      )
      .eq("class_id", validatedClassId);

    if (enrollmentError) {
      return { success: false, error: "Failed to fetch enrolled students" };
    }

    // OPTIMIZATION: Batch fetch all assessment data instead of looping (prevents N+1 queries)
    const studentIds = (enrollments || []).map((e) => e.student_id);

    // Get all assessment sessions for all students in this class in one query
    const { data: allSessions } = await supabase
      .from("assessment_sessions")
      .select("id, user_id, submitted_at")
      .in("user_id", studentIds)
      .eq("class_id", validatedClassId)
      .not("submitted_at", "is", null);

    // Get all assessment session IDs for bulk response fetch
    const sessionIds = allSessions?.map((s) => s.id) || [];

    // Get all responses for all sessions in one query (instead of per-student queries)
    const { data: allResponses } = await supabase
      .from("assessment_responses")
      .select("is_correct, session_id")
      .in("session_id", sessionIds);

    const { sessionsByStudent, responsesBySession } = buildLookupMaps(
      allSessions,
      allResponses,
    );

    const studentResults = processStudentResults(
      enrollments as unknown as Array<{
        student_id: string;
        student_profiles: { name: string; roll_number: string | null } | null;
      }>,
      sessionsByStudent,
      responsesBySession,
    );

    const studentsWithScores = studentResults.filter(
      (r) => r.averageScore !== null,
    );
    const classAverageScore =
      studentsWithScores.length > 0
        ? Math.round(
            studentsWithScores.reduce(
              (sum, r) => sum + (r.averageScore || 0),
              0,
            ) / studentsWithScores.length,
          )
        : null;

    // Verify classData exists before accessing it
    if (!auth.classData) {
      authLogger.error(
        "[getClassAssessmentResults] Missing classData in auth after authorization",
        new Error("classData undefined"),
      );
      return { success: false, error: "Class data not found" };
    }

    return {
      success: true,
      data: {
        classId: validatedClassId,
        className: auth.classData.name,
        totalStudents: enrollments?.length || 0,
        studentsWithAssessments: studentsWithScores.length,
        classAverageScore,
        results: studentResults.sort((a, b) => {
          // Sort by roll number if available, otherwise by name
          if (a.rollNumber && b.rollNumber) {
            return a.rollNumber.localeCompare(b.rollNumber);
          }
          return a.studentName.localeCompare(b.studentName);
        }),
      },
    };
  } catch (error) {
    if (error instanceof z.ZodError) {
      const firstError = error.issues[0];
      return { success: false, error: firstError?.message || "Invalid input" };
    }
    authLogger.error("[getClassAssessmentResults] Unexpected error", error);
    return {
      success: false,
      error:
        error instanceof Error ? error.message : "An unexpected error occurred",
    };
  }
}

/**
 * Internal function to fetch teacher assessment overview from database
 * This is wrapped by getTeacherAssessmentOverview() with query caching
 */
async function fetchTeacherAssessmentOverviewFromDB(
  teacherId: string,
): Promise<{
  classes: Array<{
    classId: string;
    className: string;
    subject: string | null;
    studentCount: number;
    assessmentsTaken: number;
    averageScore: number | null;
  }>;
  totalAssessments: number;
  overallAverageScore: number | null;
}> {
  const supabase = await createClient();

  // Get all classes for this teacher
  const { data: classes, error: classesError } = await supabase
    .from("classes")
    .select("id, name, subject")
    .eq("teacher_id", teacherId)
    .order("created_at", { ascending: false });

  if (classesError) {
    throw classesError;
  }

  const classResults = [];
  let totalAssessments = 0;
  let totalScore = 0;
  let scoredAssessments = 0;

  // OPTIMIZATION: Batch fetch all data for all classes (prevents N+1 queries)
  const classIds = (classes || []).map((c) => c.id);

  // Get enrollment counts for all classes in one query
  const { data: allEnrollments } = await supabase
    .from("enrollments")
    .select("class_id")
    .in("class_id", classIds);

  // Get all assessment sessions for all classes in one query
  const { data: allSessions } = await supabase
    .from("assessment_sessions")
    .select("id, class_id")
    .in("class_id", classIds)
    .not("submitted_at", "is", null);

  // Get all responses for all sessions in one query
  const sessionIds = allSessions?.map((s) => s.id) || [];
  const { data: allResponses } = await supabase
    .from("assessment_responses")
    .select("is_correct, session_id")
    .in("session_id", sessionIds);

  // Build lookup maps for efficient data association
  const enrollmentCountByClass = new Map<string, number>();
  const sessionsByClass = new Map<string, string[]>();
  const responseCountBySession = new Map<
    string,
    { correct: number; total: number }
  >();

  // Count enrollments by class
  allEnrollments?.forEach((enrollment) => {
    const count = (enrollmentCountByClass.get(enrollment.class_id) || 0) + 1;
    enrollmentCountByClass.set(enrollment.class_id, count);
  });

  // Index sessions by class_id
  allSessions?.forEach((session) => {
    if (!sessionsByClass.has(session.class_id)) {
      sessionsByClass.set(session.class_id, []);
    }
    const classSessions = sessionsByClass.get(session.class_id);
    if (classSessions) {
      classSessions.push(session.id);
    }
  });

  // Count responses per session (both correct and total) in single pass
  allResponses?.forEach((response) => {
    const current = responseCountBySession.get(response.session_id) || {
      correct: 0,
      total: 0,
    };
    current.total += 1;
    if (response.is_correct) {
      current.correct += 1;
    }
    responseCountBySession.set(response.session_id, current);
  });

  // Process class results using pre-fetched data (no queries in loop)
  for (const cls of classes || []) {
    const studentCount = enrollmentCountByClass.get(cls.id) || 0;
    const sessions = sessionsByClass.get(cls.id) || [];
    const assessmentsTaken = sessions.length;
    totalAssessments += assessmentsTaken;

    // Calculate average score from pre-fetched responses
    let averageScore: number | null = null;
    if (sessions.length > 0) {
      let totalCorrect = 0;
      let totalQuestions = 0;

      for (const sessionId of sessions) {
        const counts = responseCountBySession.get(sessionId);
        if (counts) {
          totalCorrect += counts.correct;
          totalQuestions += counts.total;
        }
      }

      if (totalQuestions > 0) {
        averageScore = Math.round((totalCorrect / totalQuestions) * 100);
        totalScore += averageScore;
        scoredAssessments++;
      }
    }

    classResults.push({
      classId: cls.id,
      className: cls.name,
      subject: cls.subject,
      studentCount,
      assessmentsTaken,
      averageScore,
    });
  }

  const overallAverageScore =
    scoredAssessments > 0 ? Math.round(totalScore / scoredAssessments) : null;

  return {
    classes: classResults,
    totalAssessments,
    overallAverageScore,
  };
}

export async function getTeacherAssessmentOverview(): Promise<{
  success: boolean;
  data?: {
    classes: Array<{
      classId: string;
      className: string;
      subject: string | null;
      studentCount: number;
      assessmentsTaken: number;
      averageScore: number | null;
    }>;
    totalAssessments: number;
    overallAverageScore: number | null;
  };
  error?: string;
}> {
  try {
    // SECURITY: Verify caller is authenticated and is a teacher
    const auth = await verifyTeacherAuth("getTeacherAssessmentOverview");
    if (!auth.authorized) {
      return auth.error;
    }

    // PERFORMANCE: Use query cache - 3 minute TTL for teacher dashboard
    // Teacher dashboards change more frequently than admin, so shorter TTL
    const data = await queryCache.getOrFetch(
      `teacher:${auth.user.id}:assessment:overview`,
      () => fetchTeacherAssessmentOverviewFromDB(auth.user.id),
      3 * 60 * 1000, // 3 minutes
    );

    return {
      success: true,
      data,
    };
  } catch (error) {
    authLogger.error("[getTeacherAssessmentOverview] Unexpected error", error);
    return {
      success: false,
      error:
        error instanceof Error ? error.message : "An unexpected error occurred",
    };
  }
}

"use server";

import { revalidatePath } from "next/cache";
import { createClient, verifyClassOwnership } from "@/lib/supabase-server";
import { checkTeacherMutationRateLimit } from "@/lib/rate-limiter-distributed";
import { EnrollmentSchema, ClassIdSchema } from "@/lib/validation-schemas";
import { authLogger } from "@/lib/auth-logger";
import { handleZodError } from "@/lib/action-error-handler";

/**
 * Student enrollment management for teacher classes
 * Handles enrolling and removing students from classes
 */

export async function enrollStudent(classId: string, studentId: string) {
  try {
    // Validate inputs
    let validatedInput;
    try {
      validatedInput = EnrollmentSchema.parse({ classId, studentId });
    } catch (error) {
      return handleZodError(error);
    }

    // SECURITY: Verify caller is authenticated and owns this class
    const auth = await verifyClassOwnership(
      "enrollStudent",
      validatedInput.classId,
    );
    if (!auth.authorized) {
      return auth.error;
    }

    // SECURITY: Rate limit teacher mutations to prevent abuse
    const enrollmentAllowed = await checkTeacherMutationRateLimit(auth.user.id);
    if (!enrollmentAllowed) {
      authLogger.warn("[enrollStudent] Rate limit exceeded", {
        userId: auth.user.id,
      });
      return {
        success: false,
        error: "Too many requests. Please try again later.",
      };
    }

    const supabase = await createClient();

    const { data, error } = await supabase
      .from("enrollments")
      .insert({
        class_id: validatedInput.classId,
        student_id: validatedInput.studentId,
      })
      .select()
      .single();

    if (error) {
      if (error.code === "23505") {
        // Unique constraint violation
        return { success: false, error: "Student is already enrolled" };
      }
      return { success: false, error: error.message };
    }

    revalidatePath(`/app/teacher/classes/${validatedInput.classId}`);
    return { success: true, data };
  } catch (error) {
    authLogger.error("[enrollStudent] Unexpected error", error);
    return {
      success: false,
      error:
        error instanceof Error ? error.message : "An unexpected error occurred",
    };
  }
}

export async function removeStudent(classId: string, studentId: string) {
  try {
    // Validate inputs
    let validatedInput;
    try {
      validatedInput = EnrollmentSchema.parse({ classId, studentId });
    } catch (error) {
      return handleZodError(error);
    }

    // SECURITY: Verify caller is authenticated and owns this class
    const auth = await verifyClassOwnership(
      "removeStudent",
      validatedInput.classId,
    );
    if (!auth.authorized) {
      return auth.error;
    }

    // SECURITY: Rate limit teacher mutations to prevent abuse
    const removalAllowed = await checkTeacherMutationRateLimit(auth.user.id);
    if (!removalAllowed) {
      authLogger.warn("[removeStudent] Rate limit exceeded", {
        userId: auth.user.id,
      });
      return {
        success: false,
        error: "Too many requests. Please try again later.",
      };
    }

    const supabase = await createClient();

    const { error } = await supabase
      .from("enrollments")
      .delete()
      .eq("class_id", validatedInput.classId)
      .eq("student_id", validatedInput.studentId);

    if (error) {
      return { success: false, error: error.message };
    }

    revalidatePath(`/app/teacher/classes/${validatedInput.classId}`);
    return { success: true };
  } catch (error) {
    authLogger.error("[removeStudent] Unexpected error", error);
    return {
      success: false,
      error:
        error instanceof Error ? error.message : "An unexpected error occurred",
    };
  }
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "sonner";
import { CLIPBOARD_TIMING } from "@/lib/constants/ui-timings";
import {
  rotateStaffPin,
  searchSchools,
  checkAdminAuth,
} from "@/app/actions/school";
import {
  getDistricts,
  getBlocksByDistrict,
  getSchoolsByDistrictAndBlock,
  getSchoolPinStatus,
  type District,
  type Block,
  type SchoolData,
} from "@/app/actions/school-finder";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Calendar,
  Shield,
  RefreshCw,
  Search,
  Copy,
  Check,
  MapPin,
} from "lucide-react";

// School Finder Modal Component
function SchoolFinderModal({
  isOpen,
  onClose,
  onSelectSchool,
}: {
  isOpen: boolean;
  onClose: () => void;
  onSelectSchool: (school: SchoolData) => Promise<void>;
}) {
  const [districts, setDistricts] = useState<District[]>([]);
  const [blocks, setBlocks] = useState<Block[]>([]);
  const [schools, setSchools] = useState<SchoolData[]>([]);
  const [selectedDistrict, setSelectedDistrict] = useState<string>("");
  const [selectedBlock, setSelectedBlock] = useState<string>("");
  const [loading, setLoading] = useState(false);

  // Load districts on mount
  useEffect(() => {
    if (isOpen) {
      loadDistricts();
    }
  }, [isOpen]);

  // Load blocks when district changes
  useEffect(() => {
    if (selectedDistrict) {
      // Clear dependent state BEFORE async load (prevent race condition)
      setSelectedBlock("");
      setSchools([]);
      // loadBlocks() will set blocks asynchronously when fetch completes
      loadBlocks();
    }
  }, [selectedDistrict]);

  // Load schools when district OR block changes
  useEffect(() => {
    if (selectedDistrict) {
      loadSchools();
    }
  }, [selectedDistrict, selectedBlock]);

  async function loadDistricts() {
    setLoading(true);
    try {
      const result = await getDistricts();
      if (result.success) {
        setDistricts(result.data);
      } else {
        toast.error(result.error || "Failed to load districts");
      }
    } catch (_error) {
      toast.error("An error occurred");
    } finally {
      setLoading(false);
    }
  }

  async function loadBlocks() {
    if (!selectedDistrict) return;

    // Clear blocks state BEFORE fetch to show loading state cleanly (prevent flicker)
    setBlocks([]);
    setLoading(true);
    try {
      const result = await getBlocksByDistrict(selectedDistrict);
      if (result.success) {
        setBlocks(result.data);
      } else {
        toast.error(result.error || "Failed to load blocks");
      }
    } catch (_error) {
      toast.error("An error occurred");
    } finally {
      setLoading(false);
    }
  }

  async function loadSchools() {
    if (!selectedDistrict) return;

    setLoading(true);
    try {
      const result = await getSchoolsByDistrictAndBlock(
        selectedDistrict,
        selectedBlock || undefined,
      );
      if (result.success) {
        setSchools(result.data);
      } else {
        toast.error(result.error || "Failed to load schools");
      }
    } catch (_error) {
      toast.error("An error occurred");
    } finally {
      setLoading(false);
    }
  }

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-96 overflow-auto">
        <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
          <MapPin className="h-5 w-5" />
          Find School by Location
        </h2>

        {/* District Selection */}
        <div className="mb-4">
          <Label className="text-sm font-semibold mb-2 block">District</Label>
          <select
            value={selectedDistrict}
            onChange={(e) => setSelectedDistrict(e.target.value)}
            className="w-full border border-border rounded-lg p-2 text-sm"
            disabled={loading}
          >
            <option value="">-- Select District --</option>
            {districts.map((d) => (
              <option key={d.name} value={d.name}>
                {d.name}
              </option>
            ))}
          </select>
        </div>

        {/* Block Selection */}
        {selectedDistrict && (
          <div className="mb-4">
            <Label className="text-sm font-semibold mb-2 block">Block</Label>
            <select
              value={selectedBlock}
              onChange={(e) => setSelectedBlock(e.target.value)}
              className="w-full border border-border rounded-lg p-2 text-sm"
              disabled={loading}
            >
              <option value="">-- All Blocks --</option>
              {blocks.map((b) => (
                <option key={b.name} value={b.name}>
                  {b.name || "Not Specified"}
                </option>
              ))}
            </select>
          </div>
        )}

        {/* Schools List */}
        {schools.length > 0 && (
          <div className="border border-border rounded-lg divide-y max-h-64 overflow-y-auto">
            {schools.map((school) => (
              <button
                key={school.id}
                onClick={async () => {
                  try {
                    await onSelectSchool(school);
                  } finally {
                    onClose();
                  }
                }}
                className="w-full text-left p-3 hover:bg-surface transition-colors"
                disabled={loading}
              >
                <div className="font-semibold text-sm text-foreground">
                  {school.school_name}
                </div>
                <div className="text-xs text-text-secondary mt-1">
                  <strong>Code:</strong> {school.school_code} •{" "}
                  <strong>Block:</strong> {school.block || "N/A"}
                </div>
                {school.address && (
                  <div className="text-xs text-text-tertiary mt-1">
                    {school.address}
                  </div>
                )}
              </button>
            ))}
          </div>
        )}

        {selectedDistrict && schools.length === 0 && !loading && (
          <div className="text-center py-4 text-text-tertiary text-sm">
            No schools found in{" "}
            {selectedBlock ? `${selectedBlock} block` : "this district"}
          </div>
        )}

        {/* Close Button */}
        <Button
          onClick={onClose}
          variant="outline"
          size="sm"
          className="mt-4 w-full"
        >
          Close
        </Button>
      </div>
    </div>
  );
}

// Copy to Clipboard Component
function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);

  function handleCopy() {
    navigator.clipboard.writeText(text);
    setCopied(true);
    toast.success("Code copied to clipboard");
    setTimeout(() => setCopied(false), CLIPBOARD_TIMING.successFeedback);
  }

  return (
    <button
      onClick={handleCopy}
      className={`p-2 rounded transition-all ${
        copied
          ? "bg-success-light text-success"
          : "bg-surface hover:bg-surface-dark text-text-secondary"
      }`}
      title="Copy to clipboard"
    >
      {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
    </button>
  );
}

// Main Admin Panel
export default function AdminSchoolsPage() {
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<SchoolData[]>([]);
  const [finderModalOpen, setFinderModalOpen] = useState(false);
  const [authorized, setAuthorized] = useState<boolean | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);

  // Check admin authorization on mount
  useEffect(() => {
    async function verifyAuth() {
      try {
        const result = await checkAdminAuth();
        if (result.authorized) {
          setAuthorized(true);
        } else {
          setAuthorized(false);
          setAuthError(result.error || "Unauthorized");
        }
      } catch (_error) {
        setAuthorized(false);
        setAuthError("Failed to verify authorization");
      }
    }

    verifyAuth();
  }, []);

  // Selected school data
  const [selectedSchool, setSelectedSchool] = useState<{
    id: string;
    code: string;
    name: string;
  } | null>(null);

  // PIN Rotation form
  const [schoolCode, setSchoolCode] = useState("");
  const [newPin, setNewPin] = useState("");
  const [confirmPin, setConfirmPin] = useState("");

  // PIN status
  const [pinStatus, setPinStatus] = useState<{
    exists: boolean;
    createdAt?: string;
    lastRotatedAt?: string;
  } | null>(null);

  // Search schools by code or name
  async function handleSearch() {
    if (!searchQuery.trim()) {
      toast.error("Please enter a school code or name");
      return;
    }

    setLoading(true);
    try {
      const result = await searchSchools(searchQuery);
      if (result.success && result.data) {
        setSearchResults(result.data);
        if (result.data.length === 0) {
          toast.info("No schools found matching your search");
        }
      } else {
        toast.error(result.error || "Failed to search schools");
      }
    } catch (_error) {
      toast.error("An error occurred while searching");
    } finally {
      setLoading(false);
    }
  }

  // Handle school selection from search or finder
  async function handleSelectSchool(school: SchoolData) {
    setSelectedSchool({
      id: school.id,
      code: school.school_code,
      name: school.school_name,
    });
    setSchoolCode(school.school_code);
    setSearchResults([]);
    setSearchQuery("");

    // Auto-fetch PIN status
    await handleGetPinStatus(school.school_code);
  }

  // Get PIN status
  async function handleGetPinStatus(code: string) {
    const codeToCheck = code || schoolCode;
    if (!codeToCheck.trim()) {
      toast.error("Please enter a school code");
      return;
    }

    setLoading(true);
    try {
      const result = await getSchoolPinStatus(codeToCheck.toUpperCase().trim());
      if (result.success) {
        setPinStatus({
          exists: result.exists,
          createdAt: result.createdAt,
          lastRotatedAt: result.lastRotatedAt,
        });
      } else {
        toast.error(result.error || "Failed to fetch PIN status");
      }
    } catch (_error) {
      toast.error("An error occurred");
    } finally {
      setLoading(false);
    }
  }

  // Rotate or create PIN
  async function handleRotatePin(e: React.FormEvent) {
    e.preventDefault();

    if (!schoolCode.trim()) {
      toast.error("Please enter a school code");
      return;
    }

    if (newPin.length < 4) {
      toast.error("PIN must be at least 4 characters long");
      return;
    }

    if (newPin !== confirmPin) {
      toast.error("PINs do not match");
      return;
    }

    setLoading(true);
    try {
      const result = await rotateStaffPin(
        schoolCode.toUpperCase().trim(),
        newPin,
      );

      if (result.success) {
        const action = pinStatus?.exists ? "rotated" : "created";
        toast.success(`PIN ${action} successfully for ${result.schoolName}`);
        setNewPin("");
        setConfirmPin("");

        // Refresh PIN status
        await handleGetPinStatus(schoolCode);
      } else {
        toast.error(result.error || "Failed to rotate PIN");
      }
    } catch (_error) {
      toast.error("An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  }

  // Show loading state
  if (authorized === null) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-surface via-background to-surface p-6 flex items-center justify-center">
        <div className="text-center">
          <p className="text-text-secondary">Verifying authorization...</p>
        </div>
      </div>
    );
  }

  // Show authorization error and redirect to admin login
  if (!authorized || authError) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-surface via-background to-surface p-6 flex items-center justify-center">
        <div className="max-w-md mx-auto text-center">
          <Shield className="h-12 w-12 text-error mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-foreground mb-2">
            Access Denied
          </h1>
          <p className="text-text-secondary mb-6">
            {authError ||
              "You do not have permission to access this page. Admin access required."}
          </p>
          <div className="space-y-3">
            <Button
              onClick={() => (globalThis.location.href = "/admin/login")}
              className="w-full"
              variant="default"
            >
              Admin Login
            </Button>
            <Button
              onClick={() => (globalThis.location.href = "/")}
              variant="outline"
              className="w-full"
            >
              Go Back Home
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-surface via-background to-surface p-6">
      <div className="max-w-3xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-center gap-3 mb-8">
          <Shield className="h-8 w-8 text-primary" />
          <div className="text-center">
            <h1 className="text-2xl font-bold text-foreground">
              School PIN Management
            </h1>
            <p className="text-xs text-text-secondary">
              Manage staff PINs and verify rotation history
            </p>
          </div>
        </div>

        {/* School Finder Modal */}
        <SchoolFinderModal
          isOpen={finderModalOpen}
          onClose={() => setFinderModalOpen(false)}
          onSelectSchool={handleSelectSchool}
        />

        {/* Step 1: Find School */}
        <div className="mb-6 p-6 bg-white border border-primary/20 rounded-lg">
          <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <Search className="h-5 w-5 text-primary" />
            Step 1: Find School
          </h2>

          <div className="space-y-4">
            {/* Quick Search */}
            <div>
              <Label className="text-sm font-medium mb-2 block">
                Quick Search by Code or Name
              </Label>
              <div className="flex gap-2">
                <Input
                  placeholder="e.g., 14H0182 or School Name"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                  disabled={loading}
                  className="flex-1"
                />
                <Button
                  onClick={handleSearch}
                  disabled={loading}
                  loading={loading}
                  size="sm"
                  className="shadow-[var(--shadow-primary-sm)]"
                >
                  <Search className="h-4 w-4" />
                </Button>
              </div>
            </div>

            {/* Search Results */}
            {searchResults.length > 0 && (
              <div className="border border-border rounded-lg divide-y max-h-48 overflow-y-auto">
                {searchResults.map((school) => (
                  <button
                    key={school.id}
                    onClick={() => handleSelectSchool(school)}
                    className="w-full text-left p-3 hover:bg-surface transition-colors flex justify-between items-center"
                  >
                    <div>
                      <div className="font-semibold text-sm text-foreground">
                        {school.school_name}
                      </div>
                      <div className="text-xs text-text-secondary mt-1">
                        {school.school_code} • {school.district}
                      </div>
                    </div>
                    <Copy className="h-4 w-4 text-text-tertiary" />
                  </button>
                ))}
              </div>
            )}

            {/* Hierarchical Finder Button */}
            <Button
              onClick={() => setFinderModalOpen(true)}
              variant="outline"
              size="sm"
              className="w-full"
            >
              <MapPin className="h-4 w-4 mr-2" />
              Or Browse by District &amp; Block
            </Button>
          </div>

          {/* Selected School Display */}
          {selectedSchool && (
            <div className="mt-4 bg-success-light border-l-4 border-success p-4 rounded">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-xs text-success font-semibold">
                    ✓ Selected School
                  </p>
                  <p className="text-sm text-success font-semibold mt-1">
                    {selectedSchool.name}
                  </p>
                  <p className="text-xs text-success font-mono mt-1">
                    Code: {selectedSchool.code}
                  </p>
                </div>
                <CopyButton text={selectedSchool.code} />
              </div>
            </div>
          )}
        </div>

        {/* Step 2: Check/Create PIN */}
        {selectedSchool && (
          <div className="mb-6 p-6 bg-white border border-primary/20 rounded-lg">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Calendar className="h-5 w-5 text-primary" />
              Step 2: PIN Status
            </h2>

            <div className="space-y-4">
              {pinStatus ? (
                pinStatus.exists ? (
                  <div className="bg-cyan-lightest border-l-4 border-cyan p-4 rounded">
                    <p className="text-xs text-cyan-darkest font-semibold">
                      ✓ PIN Exists
                    </p>
                    <p className="text-sm text-cyan-darkest mt-2">
                      <strong>Created:</strong>{" "}
                      {pinStatus.createdAt
                        ? new Date(pinStatus.createdAt).toLocaleDateString()
                        : "N/A"}
                    </p>
                    {pinStatus.lastRotatedAt && (
                      <p className="text-sm text-cyan-darkest">
                        <strong>Last Rotated:</strong>{" "}
                        {new Date(pinStatus.lastRotatedAt).toLocaleDateString()}
                      </p>
                    )}
                    <p className="text-xs text-cyan-dark mt-3 font-semibold">
                      👇 Scroll down to Step 3 to rotate the PIN
                    </p>
                  </div>
                ) : (
                  <div className="bg-warning-light border-l-4 border-warning p-4 rounded">
                    <p className="text-xs text-warning-dark font-semibold">
                      ⚠ No PIN Found
                    </p>
                    <p className="text-sm text-warning-dark mt-2">
                      This school doesn&apos;t have a PIN yet. Create one in
                      Step 3.
                    </p>
                    <p className="text-xs text-warning mt-3 font-semibold">
                      👇 Scroll down to Step 3 to create the PIN
                    </p>
                  </div>
                )
              ) : (
                <Button
                  onClick={() => handleGetPinStatus(schoolCode)}
                  variant="outline"
                  size="sm"
                  loading={loading}
                >
                  Check PIN Status
                </Button>
              )}
            </div>
          </div>
        )}

        {/* Step 3: Rotate/Create PIN */}
        {selectedSchool && (
          <div className="p-6 bg-white border border-primary/20 rounded-lg">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <RefreshCw className="h-5 w-5 text-primary" />
              Step 3: {pinStatus?.exists ? "Rotate" : "Create"} PIN
            </h2>

            <form onSubmit={handleRotatePin} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="school-code-rotate" className="text-sm">
                  School Code
                </Label>
                <Input
                  id="school-code-rotate"
                  type="text"
                  value={schoolCode}
                  disabled
                  className="bg-surface uppercase font-mono text-sm"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="new-pin" className="text-sm">
                  {pinStatus?.exists ? "New" : ""} Staff PIN
                </Label>
                <Input
                  id="new-pin"
                  type="password"
                  placeholder="e.g., 1234"
                  value={newPin}
                  onChange={(e) => setNewPin(e.target.value)}
                  required
                  disabled={loading}
                  minLength={4}
                  className="font-mono text-sm"
                />
                <p className="text-xs text-text-secondary">
                  Min 4 characters (numeric recommended)
                </p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="confirm-pin" className="text-sm">
                  Confirm PIN
                </Label>
                <Input
                  id="confirm-pin"
                  type="password"
                  placeholder="Re-enter PIN"
                  value={confirmPin}
                  onChange={(e) => setConfirmPin(e.target.value)}
                  required
                  disabled={loading}
                  minLength={4}
                  className="font-mono text-sm"
                />
              </div>

              <div className="bg-warning/10 border-l-4 border-warning p-3 rounded text-xs text-warning-dark">
                <p>
                  <strong>⚠️ Security Notice</strong>
                </p>
                <p className="mt-1">
                  PIN will be bcrypt hashed.{" "}
                  {pinStatus?.exists
                    ? "Old PIN becomes invalid immediately."
                    : "Teachers can use this PIN for registration."}
                </p>
              </div>

              <Button
                type="submit"
                className="w-full shadow-primary-hover"
                disabled={loading || newPin !== confirmPin || newPin.length < 4}
                loading={loading}
                size="lg"
              >
                <RefreshCw className="h-4 w-4 mr-2" />
                {pinStatus?.exists ? "Rotate" : "Create"} PIN
              </Button>
            </form>

            {/* Help */}
            <div className="mt-6 bg-gradient-to-r from-cream to-surface border border-primary/20 p-4 rounded-lg">
              <h3 className="font-semibold text-foreground text-sm mb-2">
                📋 Quick Guide
              </h3>
              <ul className="text-sm text-text-secondary space-y-2">
                <li>
                  <strong>Step 1:</strong> Search schools or browse by
                  district/block
                </li>
                <li>
                  <strong>Step 2:</strong> Click school → Code auto-fills →
                  Check PIN status
                </li>
                <li>
                  <strong>Step 3:</strong>{" "}
                  {pinStatus?.exists ? "Rotate" : "Create"} PIN for teachers
                </li>
                <li>
                  <strong>Result:</strong> Teachers use code + PIN for
                  registration
                </li>
              </ul>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import Link from "next/link";
import { useChat } from "ai/react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { useRequireAuth } from "@/hooks/useRequireAuth";
import { VoiceChat } from "@/components/voice/VoiceChat";

type Message = {
  id: string;
  role: "user" | "assistant";
  content: string;
};

export default function AITutorPage() {
  const { user, loading: isAuthChecking } = useRequireAuth("/student/start");
  const [language, setLanguage] = useState<"en" | "hi" | "as">("en");
  const [inputMode, setInputMode] = useState<"text" | "voice">("text");
  const [sessionId] = useState(() => crypto.randomUUID());
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Use Vercel AI SDK's useChat hook for streaming
  const { messages, input, handleInputChange, handleSubmit, isLoading, error } =
    useChat({
      api: "/api/tutor/chat",
      body: {
        language,
        sessionId,
        inputMode: "text",
      },
    });

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const suggestedQuestions = [
    "What is a computer?",
    "How does the internet work?",
    "What is email?",
    "How to stay safe online?",
  ];

  // Show loading while checking auth
  if (isAuthChecking) {
    return (
      <div className="min-h-screen bg-cream flex items-center justify-center">
        <div className="animate-pulse text-text-secondary">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-cream page-layout">
      <div className="container-responsive max-w-4xl">
        {/* Header */}
        <div className="mb-4">
          <Link
            href="/app/ai-tools"
            className="text-primary hover:text-primary-dark mb-4 inline-flex items-center gap-1 text-sm touch-target"
          >
            ← Back to AI Tools
          </Link>
          <h1 className="heading-2 text-primary mb-1">💬 AI Tutor</h1>
          <p className="text-text-secondary text-sm">
            Ask questions about digital literacy and get personalized help
          </p>
        </div>

        {/* Language & Input Mode Selectors */}
        <div className="flex flex-wrap gap-4 mb-4">
          {/* Language Selector */}
          <div className="flex gap-2">
            {(["en", "hi", "as"] as const).map((lang) => (
              <button
                key={lang}
                onClick={() => setLanguage(lang)}
                className={`px-3 py-1 rounded-full text-sm font-medium transition-colors ${
                  language === lang
                    ? "bg-primary text-white"
                    : "bg-white text-text-secondary hover:bg-primary-light"
                }`}
              >
                {lang === "en"
                  ? "English"
                  : lang === "hi"
                    ? "हिंदी"
                    : "অসমীয়া"}
              </button>
            ))}
          </div>

          {/* Input Mode Toggle */}
          <div className="flex gap-2 ml-auto">
            <button
              onClick={() => setInputMode("text")}
              className={`px-3 py-1 rounded-full text-sm font-medium transition-colors flex items-center gap-1 ${
                inputMode === "text"
                  ? "bg-primary text-white"
                  : "bg-white text-text-secondary hover:bg-primary-light"
              }`}
            >
              📝 Text
            </button>
            <button
              onClick={() => setInputMode("voice")}
              className={`px-3 py-1 rounded-full text-sm font-medium transition-colors flex items-center gap-1 ${
                inputMode === "voice"
                  ? "bg-primary text-white"
                  : "bg-white text-text-secondary hover:bg-primary-light"
              }`}
            >
              🎤 Voice
            </button>
          </div>
        </div>

        {/* Error Display */}
        {error && (
          <Card className="mb-4 border-error bg-error/10">
            <CardContent className="p-4">
              <p className="text-sm text-error">
                ⚠️ {error.message || "An error occurred. Please try again."}
              </p>
            </CardContent>
          </Card>
        )}

        {/* Chat Area */}
        <Card className="mb-4">
          <CardContent className="p-4">
            <div className="h-[400px] overflow-y-auto space-y-4 mb-4">
              {messages.length === 0 ? (
                <div className="text-center py-8">
                  <p className="text-text-secondary mb-4">
                    Start a conversation with your AI tutor!
                  </p>
                  <div className="flex flex-wrap justify-center gap-2">
                    {suggestedQuestions.map((q) => (
                      <button
                        key={q}
                        onClick={() =>
                          handleInputChange({
                            target: { value: q },
                          } as React.ChangeEvent<HTMLInputElement>)
                        }
                        className="px-3 py-2 bg-primary-light text-primary rounded-lg text-sm hover:bg-primary-lighter transition-colors"
                      >
                        {q}
                      </button>
                    ))}
                  </div>
                </div>
              ) : (
                messages.map((message) => (
                  <div
                    key={message.id}
                    className={`flex ${
                      message.role === "user" ? "justify-end" : "justify-start"
                    }`}
                  >
                    <div
                      className={`max-w-[80%] rounded-lg p-3 ${
                        message.role === "user"
                          ? "bg-primary text-white"
                          : "bg-white border border-border"
                      }`}
                    >
                      <p className="whitespace-pre-wrap text-sm">
                        {message.content}
                      </p>
                    </div>
                  </div>
                ))
              )}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="bg-white border border-border rounded-lg p-3">
                    <div className="flex gap-1">
                      <span className="w-2 h-2 bg-primary rounded-full animate-bounce" />
                      <span className="w-2 h-2 bg-primary rounded-full animate-bounce [animation-delay:0.1s]" />
                      <span className="w-2 h-2 bg-primary rounded-full animate-bounce [animation-delay:0.2s]" />
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Form - Conditional based on mode */}
            {inputMode === "voice" ? (
              <VoiceChat
                language={language}
                onTranscript={(transcript) => {
                  handleInputChange({
                    target: { value: transcript },
                  } as React.ChangeEvent<HTMLInputElement>);
                  // Auto-submit after voice input
                  setTimeout(() => {
                    const form = document.querySelector(
                      "form",
                    ) as HTMLFormElement;
                    if (form) {
                      form.requestSubmit();
                    }
                  }, 100);
                }}
                disabled={isLoading}
              />
            ) : (
              <form onSubmit={handleSubmit} className="flex gap-2">
                <input
                  type="text"
                  value={input}
                  onChange={handleInputChange}
                  placeholder="Ask a question..."
                  className="flex-1 px-4 py-2 rounded-lg border border-border focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent"
                  disabled={isLoading}
                />
                <Button type="submit" disabled={isLoading || !input.trim()}>
                  {isLoading ? "Sending..." : "Send"}
                </Button>
              </form>
            )}
          </CardContent>
        </Card>

        {/* Tips */}
        <Card className="bg-primary-light border-primary/20">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-primary">
              💡 Tips for better answers
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-0">
            <ul className="text-xs text-text-secondary space-y-1">
              <li>• Ask specific questions about digital literacy topics</li>
              <li>• Include context about what you&apos;re trying to learn</li>
              <li>• Feel free to ask follow-up questions</li>
              <li>• Watch responses appear in real-time with streaming! ⚡</li>
            </ul>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
