  progress: ModuleProgress;
  progressPercent: number;
  isUnlocked: boolean;
  index: number;
}) {
  return (
    <Card
      className={`transition-all ${
        isUnlocked
          ? "hover:shadow-lg cursor-pointer"
          : "opacity-60 cursor-not-allowed"
      } ${progress.is_complete ? "border-success border-2" : ""}`}
