"use client";

import React, { useEffect, useState } from "react";
import type { DashboardMetrics } from "@/app/actions/admin-metrics";
import {
  getDashboardMetrics,
  getSchoolsWithActivePINs,
  getAllSchools,
  getAllTeachers,
  getAllStudents,
  getSchoolsWithoutPINs,
} from "@/app/actions/admin-metrics";
import { School, Users, Lock, GraduationCap } from "lucide-react";
import { Button } from "@/components/ui/button";
import { clientLogger } from "@/lib/client-logger";
import { DataModal } from "@/components/admin/modals/DataModal";
import { ListItemCard } from "@/components/admin/modals/ListItemCard";

/**
 * ATAL AI Dashboard Metrics - Jyoti Theme
 *
 * Rule.md Compliant: Uses CSS variable classes from globals.css
 * NO hardcoded hex values - all colors via design tokens
 */

type ModalType =
  | "schools"
  | "teachers"
  | "students"
  | "activePINs"
  | "inactivePINs"
  | null;

interface SchoolItem {
  readonly id: string;
  readonly schoolName: string;
  readonly schoolCode: string;
  readonly district: string;
  readonly block?: string | null;
  readonly hasPIN?: boolean;
}

interface TeacherItem {
  readonly id: string;
  readonly email: string;
  readonly name: string;
  readonly phone: string | null;
  readonly schoolName: string;
  readonly schoolCode: string;
  readonly createdAt: string;
}

interface StudentItem {
  readonly id: string;
  readonly email: string;
  readonly phone: string | null;
  readonly createdAt: string;
  readonly lastSignIn: string | null;
}

interface ActivePINSchool {
  readonly schoolId: string;
  readonly schoolName: string;
  readonly schoolCode: string;
  readonly districtName: string;
  readonly lastRotatedAt: string | null;
}

export function DashboardMetrics() {
  const [metrics, setMetrics] = useState<DashboardMetrics | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Modal state
  const [activeModal, setActiveModal] = useState<ModalType>(null);
  const [modalLoading, setModalLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  // Data for modals
  const [schools, setSchools] = useState<SchoolItem[]>([]);
  const [teachers, setTeachers] = useState<TeacherItem[]>([]);
  const [students, setStudents] = useState<StudentItem[]>([]);
  const [activePINSchools, setActivePINSchools] = useState<ActivePINSchool[]>(
    [],
  );
  const [inactivePINSchools, setInactivePINSchools] = useState<SchoolItem[]>(
    [],
  );

  useEffect(() => {
    const loadMetrics = async () => {
      try {
        const result = await getDashboardMetrics();
        if (result.success && result.data) {
          setMetrics(result.data);
        } else {
          setError(result.error || "Failed to load metrics");
        }
      } catch {
        setError("An error occurred while loading metrics");
      } finally {
        setIsLoading(false);
      }
    };

    loadMetrics();
  }, []);

  /**
   * Helper: Load data for a specific modal type
   */
  async function loadModalData(type: ModalType): Promise<void> {
    switch (type) {
      case "schools": {
        const result = await getAllSchools();
        if (result.success && result.data) {
          setSchools(result.data);
        }
        break;
      }
      case "teachers": {
        const result = await getAllTeachers();
        if (result.success && result.data) {
          setTeachers(result.data);
        }
        break;
      }
      case "students": {
        const result = await getAllStudents();
        if (result.success && result.data) {
          setStudents(result.data);
        }
        break;
      }
      case "activePINs": {
        const result = await getSchoolsWithActivePINs();
        if (result.success && result.data) {
          setActivePINSchools(result.data);
        }
        break;
      }
      case "inactivePINs": {
        const result = await getSchoolsWithoutPINs();
        if (result.success && result.data) {
          setInactivePINSchools(result.data);
        }
        break;
      }
    }
  }

  /**
   * Open modal and load data (refactored to reduce cognitive complexity)
   * CRITICAL FIX: Reduced complexity from 17 to <15 by extracting loadModalData helper
   */
  async function openModal(type: ModalType) {
    setActiveModal(type);
    setModalLoading(true);
    setSearchQuery("");

    try {
      await loadModalData(type);
    } catch (error) {
      // Log error for debugging but don't show to user (modal will show empty state)
      clientLogger.error(
        "[DashboardMetrics] Error loading modal data",
        error instanceof Error ? error : { error: String(error) },
      );
    } finally {
      setModalLoading(false);
    }
  }

  function closeModal() {
    setActiveModal(null);
    setSearchQuery("");
  }

  /**
   * Helper: Get modal title based on type
   */
  function getModalTitle(): string {
    switch (activeModal) {
      case "schools":
        return `All Schools (${filteredSchools.length})`;
      case "teachers":
        return `All Teachers (${filteredTeachers.length})`;
      case "students":
        return `All Students (${filteredStudents.length})`;
      case "activePINs":
        return `Schools with Active PINs (${filteredActivePINs.length})`;
      case "inactivePINs":
        return `Schools without PINs (${filteredInactivePINs.length})`;
      default:
        return "";
    }
  }

  /**
   * Helper: Render modal content based on type
   * Refactored to use ListItemCard component (consolidated 80+ lines)
   */
  function renderModalContent(): React.ReactElement {
    let items: any[] = [];
    let emptyMessage = "No content";

    switch (activeModal) {
      case "schools":
        items = filteredSchools;
        emptyMessage = "No schools found";
        break;
      case "teachers":
        items = filteredTeachers;
        emptyMessage = "No teachers found";
        break;
      case "students":
        items = filteredStudents;
        emptyMessage = "No students found";
        break;
      case "activePINs":
        items = filteredActivePINs;
        emptyMessage = "No schools with active PINs";
        break;
      case "inactivePINs":
        items = filteredInactivePINs;
        emptyMessage = "All schools have active PINs";
        break;
    }

    return items.length === 0 ? (
      <p className="text-center text-text-tertiary py-8">{emptyMessage}</p>
    ) : (
      <div className="space-y-3">
        {items.map((item) => (
          <ListItemCard
            key={item.id || item.schoolId}
            item={item}
            modalType={activeModal}
          />
        ))}
      </div>
    );
  }

  // Filter functions
  const filteredSchools = schools.filter(
    (s) =>
      s.schoolName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.schoolCode.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.district.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  const filteredTeachers = teachers.filter(
    (t) =>
      t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.schoolName.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  const filteredStudents = students.filter(
    (s) =>
      s.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (s.phone && s.phone.includes(searchQuery)),
  );

  const filteredActivePINs = activePINSchools.filter(
    (s) =>
      s.schoolName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.schoolCode.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  const filteredInactivePINs = inactivePINSchools.filter(
    (s) =>
      s.schoolName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.schoolCode.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        {[...Array(5)].map((_, i) => (
          <div
            key={`skeleton-${i}`}
            className="bg-border-light rounded-lg p-4 h-24 animate-pulse"
          ></div>
        ))}
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-error-light border border-error rounded-md p-4">
        <p className="text-sm text-error-dark">{error}</p>
      </div>
    );
  }

  if (!metrics) {
    return null;
  }

  const metricCards = [
    {
      title: "Schools",
      value: metrics.totalSchools,
      icon: School,
      color: "bg-primary-light",
      iconColor: "text-primary",
      hoverColor: "hover:border-primary",
      modalType: "schools" as ModalType,
    },
    {
      title: "Teachers",
      value: metrics.totalTeachers,
      icon: Users,
      color: "bg-success-light",
      iconColor: "text-success",
      hoverColor: "hover:border-success",
      modalType: "teachers" as ModalType,
    },
    {
      title: "Students",
      value: metrics.totalStudents,
      icon: GraduationCap,
      color: "bg-accent-light",
      iconColor: "text-accent-dark",
      hoverColor: "hover:border-accent",
      modalType: "students" as ModalType,
    },
    {
      title: "Active PINs",
      value: metrics.activePins,
      icon: Lock,
      color: "bg-primary-light",
      iconColor: "text-primary",
      hoverColor: "hover:border-primary",
      modalType: "activePINs" as ModalType,
    },
    {
      title: "Inactive PINs",
      value: metrics.inactivePins,
      icon: Lock,
      color: "bg-border-light",
      iconColor: "text-text-tertiary",
      hoverColor: "hover:border-text-tertiary",
      modalType: "inactivePINs" as ModalType,
    },
  ];

  return (
    <>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        {metricCards.map((card) => {
          const Icon = card.icon;
          return (
            <button
              key={card.title}
              onClick={() => openModal(card.modalType)}
              className={`${card.color} rounded-lg p-6 border border-border text-left ${card.hoverColor} hover:shadow-md transition cursor-pointer`}
            >
              <div className="flex items-center gap-3 mb-3">
                <Icon className={`w-5 h-5 ${card.iconColor}`} />
                <h3 className="text-sm text-text-secondary font-medium">
                  {card.title}
                </h3>
              </div>
              <p className="text-3xl font-bold text-text-primary">
                {card.value}
              </p>
              <p className={`text-xs ${card.iconColor} mt-2 underline`}>
                Click to view
              </p>
            </button>
          );
        })}
      </div>

      {/* Data Display Modal (refactored to use reusable DataModal component) */}
      <DataModal
        isOpen={activeModal !== null}
        title={getModalTitle()}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        onClose={closeModal}
        isLoading={modalLoading}
      >
        {renderModalContent()}
      </DataModal>
    </>
  );
}

"use client";

/**
 * Voice Chat Component
 *
 * Implements voice I/O for the AI Tutor:
 * - Input: Web Speech API (FREE, browser-native, supports Assamese)
 * - Output: AI4Bharat TTS (FREE, Assamese emotion support)
 *
 * Language codes:
 * - en-IN: English (India)
 * - hi-IN: Hindi
 * - as-IN: Assamese
 */

import { useState, useRef, useCallback, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { clientLogger } from "@/lib/client-logger";

// Language codes for Web Speech API
const SPEECH_LANG_CODES = {
  en: "en-IN",
  hi: "hi-IN",
  as: "as-IN", // Assamese supported!
} as const;

type Language = "en" | "hi" | "as";

interface VoiceChatProps {
  readonly language: Language;
  readonly onTranscript: (text: string) => void;
  readonly onSpeakStart?: () => void;
  readonly onSpeakEnd?: () => void;
  readonly disabled?: boolean;
}

// Check for browser support
const isSpeechSupported =
  typeof globalThis !== "undefined" &&
  ("SpeechRecognition" in globalThis ||
    "webkitSpeechRecognition" in globalThis);

export function VoiceChat({
  language,
  onTranscript,
  onSpeakStart,
  onSpeakEnd,
  disabled = false,
}: VoiceChatProps) {
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [interimTranscript, setInterimTranscript] = useState("");
  const [error, setError] = useState<string | null>(null);

  const recognitionRef = useRef<SpeechRecognition | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.abort();
      }
      if (audioRef.current) {
        audioRef.current.pause();
      }
    };
  }, []);

  // Start listening with Web Speech API
  const startListening = useCallback(() => {
    if (!isSpeechSupported) {
      setError("Speech recognition not supported in this browser");
      return;
    }

    setError(null);

    const global = globalThis as typeof globalThis & {
      SpeechRecognition?: new () => SpeechRecognition;
      webkitSpeechRecognition?: new () => SpeechRecognition;
    };
    const SpeechRecognitionAPI =
      global.SpeechRecognition || global.webkitSpeechRecognition;

    if (!SpeechRecognitionAPI) {
      setError("Speech Recognition API is not supported in your browser");
      return;
    }

    const recognition = new SpeechRecognitionAPI();

    recognition.lang = SPEECH_LANG_CODES[language];
    recognition.continuous = false;
    recognition.interimResults = true;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => {
      setIsListening(true);
      setInterimTranscript("");
    };

    recognition.onresult = (event: SpeechRecognitionEvent) => {
      let interim = "";
      let final = "";

      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i];
        if (result.isFinal) {
          final += result[0].transcript;
        } else {
          interim += result[0].transcript;
        }
      }

      setInterimTranscript(interim);

      if (final) {
        onTranscript(final);
        setInterimTranscript("");
      }
    };

    recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
      clientLogger.error("[VoiceChat] Speech recognition error:", {
        errorCode: event.error,
      });

      switch (event.error) {
        case "no-speech":
          setError("No speech detected. Please try again.");
          break;
        case "audio-capture":
          setError("Microphone not found. Please check your device.");
          break;
        case "not-allowed":
          setError(
            "Microphone access denied. Please enable in browser settings.",
          );
          break;
        default:
          setError(`Speech recognition error: ${event.error}`);
      }

      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
      setInterimTranscript("");
    };

    recognition.start();
    recognitionRef.current = recognition;
  }, [language, onTranscript]);

  // Stop listening
  const stopListening = useCallback(() => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
    }
    setIsListening(false);
  }, []);

  // Browser TTS fallback using Web Speech Synthesis
  const speakWithBrowser = useCallback(
    (text: string) => {
      if (
        typeof globalThis === "undefined" ||
        !("speechSynthesis" in globalThis)
      ) {
        setError("Browser TTS not supported");
        return;
      }

      const utterance = new SpeechSynthesisUtterance(text);

      // Map language to browser TTS language codes
      const langMap = {
        en: "en-IN",
        hi: "hi-IN",
        as: "as-IN", // May fall back to Hindi if Assamese not available
      };
      utterance.lang = langMap[language] || "en-IN";
      utterance.rate = 0.9;
      utterance.pitch = 1.0;

      utterance.onend = () => {
        setIsSpeaking(false);
        onSpeakEnd?.();
      };

      utterance.onerror = () => {
        setIsSpeaking(false);
        onSpeakEnd?.();
      };

      globalThis.speechSynthesis?.speak(utterance);
    },
    [language, onSpeakEnd],
  );

  // Speak text using AI4Bharat TTS with browser fallback
  const speakText = useCallback(
    async (text: string) => {
      if (!text || isSpeaking) return;

      setIsSpeaking(true);
      onSpeakStart?.();

      try {
        const response = await fetch("/api/voice/tts", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ text, language }),
        });

        if (!response.ok) {
          // Use browser TTS as fallback
          clientLogger.warn(
            "[VoiceChat] TTS API failed, using browser fallback",
          );
          speakWithBrowser(text);
          return;
        }

        const audioBlob = await response.blob();
        const audioUrl = URL.createObjectURL(audioBlob);

        const audio = new Audio(audioUrl);
        audioRef.current = audio;

        audio.onended = () => {
          setIsSpeaking(false);
          onSpeakEnd?.();
          URL.revokeObjectURL(audioUrl);
        };

        audio.onerror = () => {
          // Fallback to browser TTS on playback error
          clientLogger.warn(
            "[VoiceChat] Audio playback failed, using browser fallback",
          );
          URL.revokeObjectURL(audioUrl);
          speakWithBrowser(text);
        };

        await audio.play();
      } catch (err) {
        clientLogger.error(
          "[VoiceChat] TTS error:",
          err instanceof Error ? err : undefined,
        );
        // Fallback to browser TTS
        speakWithBrowser(text);
      }
    },
    [language, isSpeaking, onSpeakStart, onSpeakEnd, speakWithBrowser],
  );

  // Stop speaking (handles both audio element and browser TTS)
  const stopSpeaking = useCallback(() => {
    // Stop audio element if playing
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current = null;
    }
    // Stop browser speech synthesis if active
    if (typeof globalThis !== "undefined" && "speechSynthesis" in globalThis) {
      globalThis.speechSynthesis?.cancel();
    }
    setIsSpeaking(false);
    onSpeakEnd?.();
  }, [onSpeakEnd]);

  // Toggle listening
  const toggleListening = useCallback(() => {
    if (isListening) {
      stopListening();
    } else {
      startListening();
    }
  }, [isListening, startListening, stopListening]);

  return (
    <div className="flex flex-col items-center gap-4">
      {/* Mic Button */}
      <Button
        size="lg"
        variant={isListening ? "destructive" : "default"}
        className={`w-20 h-20 rounded-full transition-all ${
          isListening ? "animate-pulse scale-110" : ""
        }`}
        onClick={toggleListening}
        disabled={disabled || isSpeaking}
      >
        {isListening ? (
          <MicOffIcon className="w-8 h-8" />
        ) : (
          <MicIcon className="w-8 h-8" />
        )}
      </Button>

      {/* Status */}
      <div className="text-center">
        {isListening && (
          <p className="text-sm text-primary font-medium animate-pulse">
            Listening...
          </p>
        )}
        {isSpeaking && (
          <div className="flex items-center gap-2">
            <p className="text-sm text-primary font-medium">Speaking...</p>
            <Button variant="outline" size="sm" onClick={stopSpeaking}>
              <VolumeOffIcon className="w-4 h-4" />
            </Button>
          </div>
        )}
        {!isListening && !isSpeaking && (
          <p className="text-sm text-muted-foreground">Tap to speak</p>
        )}
      </div>

      {/* Interim transcript */}
      {interimTranscript && (
        <p className="text-sm text-muted-foreground italic max-w-xs text-center">
          "{interimTranscript}"
        </p>
      )}

      {/* Error message */}
      {error && (
        <p className="text-sm text-error max-w-xs text-center">{error}</p>
      )}

      {/* Browser support warning */}
      {!isSpeechSupported && (
        <p className="text-sm text-warning max-w-xs text-center">
          Voice input not supported. Please use Chrome, Edge, or Safari.
        </p>
      )}
    </div>
  );
}

// Expose speakText for external use
export function useTTS(language: Language) {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const speak = useCallback(
    async (text: string) => {
      if (!text || isSpeaking) return;

      setIsSpeaking(true);

      try {
        const response = await fetch("/api/voice/tts", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ text, language }),
        });

        if (!response.ok) throw new Error("TTS failed");

        const audioBlob = await response.blob();
        const audioUrl = URL.createObjectURL(audioBlob);

        const audio = new Audio(audioUrl);
        audioRef.current = audio;

        audio.onended = () => {
          setIsSpeaking(false);
          URL.revokeObjectURL(audioUrl);
        };

        audio.onerror = () => {
          setIsSpeaking(false);
          URL.revokeObjectURL(audioUrl);
        };

        await audio.play();
      } catch (err) {
        clientLogger.error(
          "[useTTS] TTS error:",
          err instanceof Error ? err : undefined,
        );
        setIsSpeaking(false);
      }
    },
    [language, isSpeaking],
  );

  const stop = useCallback(() => {
    if (audioRef.current) {
      audioRef.current.pause();
    }
    setIsSpeaking(false);
  }, []);

  return { speak, stop, isSpeaking };
}

