interface SetPasswordStepProps extends StepComponentProps {
  password: string;
  passwordConfirm: string;
  passwordStrength: number;
  handlePasswordChange: (value: string) => void;
  setPasswordConfirm: (value: string) => void;
  handleSetPassword: (e: React.FormEvent) => Promise<void>;
}

export function SetPasswordStep({
  loading,
  password,
  passwordConfirm,
  passwordStrength,
  handlePasswordChange,
  setPasswordConfirm,
  handleSetPassword,
}: SetPasswordStepProps) {
  const getPasswordStrengthLabel = () => {
    if (password.length === 0) return "";
    const labels = ["Very Weak", "Weak", "Fair", "Good", "Strong"];
    return labels[passwordStrength] || "";
  };

  const getPasswordStrengthColor = () => {
    const colors = [
      "bg-error",
      "bg-warning",
      "bg-warning",
      "bg-cyan",
      "bg-success",
    ];
    return colors[passwordStrength] || "bg-surface-dark";
  };

  return (
    <div className="min-h-screen bg-cream flex items-center justify-center px-4 py-8 sm:px-6 md:px-8">
      <AuthCard
        title="Create Password"
        description="Step 2 of 4: Secure your account"
      >
        <form onSubmit={handleSetPassword} className="space-y-3 sm:space-y-4">
          <div className="space-y-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              placeholder="Enter password (min 8 characters)"
              value={password}
              onChange={(e) => handlePasswordChange(e.target.value)}
              required
              disabled={loading}
              minLength={8}
            />
            {password.length > 0 && (
              <div className="space-y-1">
                <div className="flex gap-1">
                  {[0, 1, 2, 3, 4].map((i) => (
                    <div
                      key={`strength-bar-${i}`}
                      className={`h-1 flex-1 rounded ${
                        i <= passwordStrength
                          ? getPasswordStrengthColor()
                          : "bg-surface-dark"
                      }`}
                    />
                  ))}
                </div>
                <p className="text-xs text-text-secondary">
                  Strength: {getPasswordStrengthLabel()}
                </p>
                {(() => {
                  const validation = validatePassword(password);
                  if (!validation.valid && validation.errors.length > 0) {
                    return (
                      <p className="text-xs text-error">
                        {validation.errors.join(", ")}
                      </p>
                    );
                  }
                  return null;
                })()}
              </div>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="password-confirm">Confirm Password</Label>
            <Input
              id="password-confirm"
              type="password"
              placeholder="Re-enter password"
              value={passwordConfirm}
              onChange={(e) => setPasswordConfirm(e.target.value)}
              required
              disabled={loading}
              minLength={8}
            />
          </div>

          <div className="bg-cyan-lightest border-l-4 border-cyan p-3 rounded-xl">
            <p className="text-xs text-cyan-darkest">
              <strong>🔒 Why a password?</strong>
              <br />A password enables account recovery and allows you to access
              your account from multiple devices securely.
            </p>
          </div>

          <Button
            type="submit"
            className="w-full shadow-[var(--shadow-primary)]"
            disabled={
              loading ||
              !validatePassword(password).valid ||
              password !== passwordConfirm
            }
            loading={loading}
          >
            Set Password & Continue
          </Button>
        </form>
      </AuthCard>
    </div>
  );
}

