  email: string;
  setEmail: (value: string) => void;
  emailError: string;
  setEmailError: (value: string) => void;
  emailSuggestion: string;
  otp: string;
  setOtp: (value: string) => void;
  otpSent: boolean;
  setOtpSent: (sent: boolean) => void;
  phoneNumber: string;
  setPhoneNumber: (value: string) => void;
  phoneError: string;
  setPhoneError: (value: string) => void;
  phoneOtp: string;
  setPhoneOtp: (value: string) => void;
  phoneOtpSent: boolean;
  setPhoneOtpSent: (sent: boolean) => void;
  handleSendOTP: (e: React.FormEvent) => Promise<void>;
  handleVerifyOTP: (e: React.FormEvent) => Promise<void>;
}

export function AuthStep({
  loading,
  signupMethod,
  setSignupMethod,
  email,
  setEmail,
  emailError,
  setEmailError,
  emailSuggestion,
  otp,
  setOtp,
  otpSent,
  setOtpSent,
  phoneNumber,
  setPhoneNumber,
  phoneError,
  setPhoneError,
  phoneOtp,
  setPhoneOtp,
  phoneOtpSent,
  setPhoneOtpSent,
  handleSendOTP,
  handleVerifyOTP,
  setStep,
  router,
}: AuthStepProps) {
  return (
    <div className="min-h-screen bg-cream flex items-center justify-center px-4 py-8 sm:px-6 md:px-8">
      <AuthCard
        title="Teacher Registration"
        description="Step 1 of 4: Choose your verification method"
      >
        <div className="space-y-3 sm:space-y-4">
          <div className="flex gap-2 sm:gap-3">
            <button
              onClick={() => {
                setSignupMethod("email");
                setPhoneError("");
                setEmailError("");
              }}
              className={`flex-1 py-2 sm:py-2.5 px-3 sm:px-4 rounded-lg font-medium transition-colors text-xs sm:text-sm ${
                signupMethod === "email"
                  ? "bg-primary text-white shadow-md"
                  : "bg-muted text-text-secondary hover:bg-muted/80"
              }`}
              disabled={loading}
            >
              <span className="hidden sm:inline">📧 </span>Email
            </button>
            <button
              onClick={() => {
                setSignupMethod("phone");
                setPhoneError("");
                setEmailError("");
              }}
              className={`flex-1 py-2 sm:py-2.5 px-3 sm:px-4 rounded-lg font-medium transition-colors text-xs sm:text-sm ${
                signupMethod === "phone"
                  ? "bg-primary text-white shadow-md"
                  : "bg-muted text-text-secondary hover:bg-muted/80"
              }`}
              disabled={loading}
            >
              <span className="hidden sm:inline">📱 </span>Phone
            </button>
          </div>

          {signupMethod === "email" && (
            <>
              {otpSent ? (
                <form onSubmit={handleVerifyOTP} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="otp">Verification Code</Label>
                    <Input
                      id="otp"
                      type="text"
                      placeholder="123456"
                      value={otp}
                      onChange={(e) =>
                        setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))
                      }
                      required
                      disabled={loading}
                      maxLength={6}
                      className="text-center text-2xl font-mono tracking-widest"
                    />
                    <p className="text-xs text-text-secondary">
                      Enter the 6-digit code sent to {email}
                    </p>
                  </div>

                  <Button
                    type="submit"
                    className="w-full shadow-[var(--shadow-primary)]"
                    disabled={loading || otp.length !== 6}
                    loading={loading}
                  >
                    Verify & Continue
                  </Button>

                  <div className="flex flex-col items-center gap-2">
                    <button
                      type="button"
                      onClick={handleSendOTP}
                      className="text-sm text-primary hover:text-primary-dark hover:underline"
                      disabled={loading}
                    >
                      Resend OTP
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        setOtpSent(false);
                        setOtp("");
                      }}
                      className="text-sm text-primary hover:underline"
                      disabled={loading}
                    >
                      Use different email
                    </button>
                  </div>
                </form>
              ) : (
                <form onSubmit={handleSendOTP} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="email">Email Address</Label>
                    <Input
                      id="email"
                      type="email"
                      placeholder="teacher@school.edu"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      required
                      disabled={loading}
                    />
                    {emailError && (
                      <div className="space-y-2">
                        <p className="text-sm text-error">{emailError}</p>
                        {emailSuggestion && (
                          <button
                            type="button"
                            onClick={() => setEmail(emailSuggestion)}
                            className="text-sm text-cyan hover:text-cyan-dark hover:underline"
                            disabled={loading}
                          >
                            ✓ Use suggested: {emailSuggestion}
                          </button>
                        )}
                      </div>
                    )}
                    <p className="text-xs text-text-secondary">
                      We&apos;ll send a 6-digit code to this email
                    </p>
                  </div>

                  <Button
                    type="submit"
                    className="w-full shadow-[var(--shadow-primary)]"
                    disabled={loading || !email}
                    loading={loading}
                  >
                    Send Verification Code
                  </Button>
                </form>
              )}
            </>
          )}

          {signupMethod === "phone" && (
            <div className="space-y-4">
              <div className="bg-cyan-lightest border-l-4 border-cyan p-3 rounded-xl">
                <p className="text-xs text-cyan-darkest">
                  <strong>📱 Phone Verification</strong>
                  <br />
                  Enter your 10-digit phone number. We&apos;ll send a
                  verification code via OTP.
                </p>
              </div>
              <form className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="phone">Phone Number</Label>
                  <div className="flex gap-2">
                    <div className="flex items-center px-3 bg-muted rounded-lg">
                      <span className="text-sm font-medium text-text-secondary">
                        +91
                      </span>
                    </div>
                    <Input
                      id="phone"
                      type="tel"
                      placeholder="9876543210"
                      value={phoneNumber}
                      onChange={(e) => {
                        const digits = e.target.value
                          .replace(/\D/g, "")
                          .slice(0, 10);
                        setPhoneNumber(digits);
                        setPhoneError("");
                      }}
                      required
                      disabled={loading}
                      maxLength={10}
                    />
                  </div>
                  {phoneError && (
                    <p className="text-sm text-error">{phoneError}</p>
                  )}
                  <p className="text-xs text-text-secondary">
                    10-digit Indian phone number
                  </p>
                </div>

                <Button
                  type="button"
                  onClick={() => {
                    if (phoneNumber.length === 10) {
                      setPhoneOtpSent(true);
                      toast.success("OTP sent to your phone!");
                    } else {
                      setPhoneError("Phone number must be 10 digits");
                    }
                  }}
                  className="w-full shadow-[var(--shadow-primary)]"
                  disabled={loading || phoneNumber.length !== 10}
                  loading={loading}
                >
                  Send OTP to Phone
                </Button>
              </form>

              {phoneOtpSent && (
                <form className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="phone-otp">Verification Code</Label>
                    <Input
                      id="phone-otp"
                      type="text"
                      placeholder="123456"
                      value={phoneOtp}
                      onChange={(e) =>
                        setPhoneOtp(
                          e.target.value.replace(/\D/g, "").slice(0, 6),
                        )
                      }
                      required
                      disabled={loading}
                      maxLength={6}
                      className="text-center text-2xl font-mono tracking-widest"
                    />
                    <p className="text-xs text-text-secondary">
                      Enter the 6-digit code sent to +91{phoneNumber}
                    </p>
                  </div>

                  <Button
                    type="button"
                    onClick={() => {
                      if (phoneOtp.length === 6) {
                        toast.success("Phone verified!");
                        setStep("set-password");
                      } else {
                        toast.error("Please enter 6-digit code");
                      }
                    }}
                    className="w-full shadow-[var(--shadow-primary)]"
                    disabled={loading || phoneOtp.length !== 6}
                    loading={loading}
                  >
                    Verify & Continue
                  </Button>

                  <button
                    type="button"
                    onClick={() => {
                      setPhoneOtpSent(false);
                      setPhoneOtp("");
                    }}
                    className="text-sm text-primary hover:underline block w-full text-center"
                    disabled={loading}
                  >
                    Change phone number
                  </button>
                </form>
              )}
            </div>
          )}

          <div className="text-center pt-2">
            <button
              type="button"
              onClick={() => setStep("choice")}
              className="text-sm text-primary hover:underline"
              disabled={loading}
            >
              ← Back to options
            </button>
          </div>
        </div>
      </AuthCard>
    </div>
  );
}

