"use client";

/**
 * Badges Display Component
 *
 * Shows earned and locked badges with cultural Assamese themes.
 * Features:
 * - 10 cultural badges (Muga Silk, Bihu, Brahmaputra, etc.)
 * - Trilingual names (English, Hindi, Assamese)
 * - Rarity tiers (common, uncommon, rare, legendary)
 * - Animated unlock effects
 */

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { createClient } from "@/lib/supabase-browser";
import { clientLogger } from "@/lib/client-logger";
import type { Badge as BaseBadge } from "@/lib/services/gamification-service";

/**
 * Display-specific Badge type with earned status
 * Extends base Badge but makes unlock_criteria optional (not needed for display)
 * and adds earned_at for tracking when the badge was earned
 */
interface DisplayBadge extends Omit<
  BaseBadge,
  "unlock_criteria" | "cultural_note"
> {
  readonly cultural_note: string | null;
  readonly earned_at?: string;
}

interface BadgesDisplayProps {
  readonly studentId: string;
  readonly language?: "en" | "hi" | "as";
  readonly showAll?: boolean;
}

// Rarity colors and styles - using semantic CSS variables where possible
const RARITY_STYLES = {
  common: {
    bg: "bg-muted",
    border: "border-muted-foreground/30",
    text: "text-muted-foreground",
    glow: "",
  },
  uncommon: {
    bg: "bg-success/10",
    border: "border-success",
    text: "text-success",
    glow: "shadow-success/20",
  },
  rare: {
    bg: "bg-primary/10",
    border: "border-primary",
    text: "text-primary",
    glow: "shadow-primary/30",
  },
  legendary: {
    bg: "bg-gradient-to-br from-warning/20 to-warning/10",
    border: "border-warning",
    text: "text-warning",
    glow: "shadow-warning/30 shadow-lg",
  },
};

export function BadgesDisplay({
  studentId,
  language = "en",
  showAll = true,
}: BadgesDisplayProps) {
  const [badges, setBadges] = useState<DisplayBadge[]>([]);
  const [earnedIds, setEarnedIds] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [selectedBadge, setSelectedBadge] = useState<DisplayBadge | null>(null);

  useEffect(() => {
    fetchBadges();
  }, [studentId]);

  const fetchBadges = async () => {
    try {
      const supabase = createClient();

      // Fetch all badges from the database
      const { data: badgesData, error: badgesError } = await supabase
        .from("badges")
        .select("*")
        .order("rarity", { ascending: true });

      if (badgesError) {
        clientLogger.error("[BadgesDisplay] Error fetching badges:", {
          message: badgesError.message,
        });
        setBadges([]);
        setEarnedIds(new Set());
        setLoading(false);
        return;
      }

      // Fetch student's earned badges
      const { data: earnedData, error: earnedError } = await supabase
        .from("student_badges")
        .select("badge_id, earned_at")
        .eq("student_id", studentId);

      if (earnedError) {
        clientLogger.error("[BadgesDisplay] Error fetching earned badges:", {
          message: earnedError.message,
        });
      }

      // Map database badges to component format
      const allBadges: DisplayBadge[] = (badgesData || []).map((b) => ({
        id: b.id,
        name_en: b.name_en,
        name_hi: b.name_hi,
        name_as: b.name_as,
        description: b.description,
        icon: b.icon,
        cultural_note: b.cultural_note,
        rarity: b.rarity as "common" | "uncommon" | "rare" | "legendary",
        points_value: b.points_value || 100,
        earned_at: earnedData?.find((e) => e.badge_id === b.id)?.earned_at,
      }));

      // Create set of earned badge IDs
      const earnedSet = new Set(earnedData?.map((e) => e.badge_id) || []);

      setBadges(allBadges);
      setEarnedIds(earnedSet);
      setLoading(false);
    } catch (error) {
      clientLogger.error(
        "[BadgesDisplay] Error:",
        error instanceof Error ? error : undefined,
      );
      setBadges([]);
      setEarnedIds(new Set());
      setLoading(false);
    }
  };

  const getBadgeName = (badge: DisplayBadge) => {
    switch (language) {
      case "as":
        return badge.name_as;
      case "hi":
        return badge.name_hi;
      default:
        return badge.name_en;
    }
  };

  const earnedBadges = badges.filter((b) => earnedIds.has(b.id));
  const lockedBadges = badges.filter((b) => !earnedIds.has(b.id));
  const displayBadges = showAll ? badges : earnedBadges;

  if (loading) {
    return (
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
        {[1, 2, 3, 4, 5].map((i) => (
          <div key={`badge-skeleton-${i}`} className="animate-pulse">
            <div className="w-20 h-20 mx-auto bg-muted rounded-full" />
            <div className="h-4 bg-muted rounded mt-2 mx-4" />
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Stats Summary */}
      <div className="flex justify-center gap-8 text-center">
        <div>
          <div className="text-3xl font-bold text-primary">
            {earnedBadges.length}
          </div>
          <div className="text-sm text-muted-foreground">Earned</div>
        </div>
        <div>
          <div className="text-3xl font-bold text-muted-foreground">
            {lockedBadges.length}
          </div>
          <div className="text-sm text-muted-foreground">Locked</div>
        </div>
        <div>
          <div className="text-3xl font-bold text-warning">
            {earnedBadges.reduce((sum, b) => sum + b.points_value, 0)}
          </div>
          <div className="text-sm text-muted-foreground">Points</div>
        </div>
      </div>

      {/* Badges Grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
        {displayBadges.map((badge) => {
          const isEarned = earnedIds.has(badge.id);
          const styles = RARITY_STYLES[badge.rarity];

          return (
            <button
              key={badge.id}
              onClick={() => setSelectedBadge(badge)}
              className={`group relative p-4 rounded-xl border-2 transition-all duration-300 ${
                isEarned
                  ? `${styles.bg} ${styles.border} ${styles.glow} hover:scale-105`
                  : "bg-muted/50 border-dashed border-muted-foreground/30 opacity-60"
              }`}
            >
              {/* Badge Icon */}
              <div
                className={`text-4xl mb-2 transition-transform ${
                  isEarned ? "group-hover:scale-110" : "grayscale"
                }`}
              >
                {badge.icon}
              </div>

              {/* Badge Name */}
              <div
                className={`text-sm font-medium ${isEarned ? styles.text : "text-muted-foreground"}`}
              >
                {getBadgeName(badge)}
              </div>

              {/* Rarity Indicator */}
              <div
                className={`text-xs mt-1 capitalize ${
                  isEarned ? styles.text : "text-muted-foreground"
                }`}
              >
                {badge.rarity}
              </div>

              {/* Lock Icon for Locked Badges */}
              {!isEarned && (
                <div className="absolute top-2 right-2 text-muted-foreground">
                  🔒
                </div>
              )}

              {/* Points */}
              <div className="absolute bottom-2 right-2 text-xs text-muted-foreground">
                +{badge.points_value}
              </div>
            </button>
          );
        })}
      </div>

      {/* Badge Detail Modal */}
      {selectedBadge && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="badge-modal-title"
          className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
          onClick={() => setSelectedBadge(null)}
          onKeyDown={(e) => {
            if (e.key === "Escape") setSelectedBadge(null);
          }}
        >
          <Card
            className="max-w-md w-full"
            onClick={(e) => e.stopPropagation()}
          >
            <CardContent className="p-6 text-center">
              {/* Icon */}
              <div className="text-6xl mb-4">{selectedBadge.icon}</div>

              {/* Name in all languages */}
              <h3 id="badge-modal-title" className="text-xl font-bold">
                {selectedBadge.name_en}
              </h3>
              <p className="text-muted-foreground">{selectedBadge.name_as}</p>
              <p className="text-sm text-muted-foreground">
                {selectedBadge.name_hi}
              </p>

              {/* Description */}
              <p className="mt-4 text-sm">{selectedBadge.description}</p>

              {/* Cultural Note */}
              {selectedBadge.cultural_note && (
                <p className="mt-4 text-sm italic text-warning bg-warning/10 p-3 rounded-lg">
                  🏔️ {selectedBadge.cultural_note}
                </p>
              )}

              {/* Status */}
              <div className="mt-4">
                {earnedIds.has(selectedBadge.id) ? (
                  <span className="inline-block px-4 py-2 bg-success/10 text-success rounded-full font-medium">
                    ✓ Earned • +{selectedBadge.points_value} points
                  </span>
                ) : (
                  <span className="inline-block px-4 py-2 bg-muted text-muted-foreground rounded-full">
                    🔒 Locked
                  </span>
                )}
              </div>

              {/* Close Button */}
              <button
                type="button"
                onClick={() => setSelectedBadge(null)}
                className="mt-4 text-sm text-muted-foreground hover:text-primary"
                aria-label="Close badge details"
              >
                Close
              </button>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

/**
 * Compact Badge Display for Dashboard
 */
export function BadgesCompact({
  badges,
  maxDisplay = 5,
}: {
  readonly badges: Array<{ id: string; icon: string; name: string }>;
  readonly maxDisplay?: number;
}) {
  const displayBadges = badges.slice(0, maxDisplay);
  const remaining = badges.length - maxDisplay;

  return (
    <div className="flex items-center gap-1">
      {displayBadges.map((badge) => (
        <div
          key={badge.id}
          className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-lg"
          title={badge.name}
        >
          {badge.icon}
        </div>
      ))}
      {remaining > 0 && (
        <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center text-xs font-medium">
          +{remaining}
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * Leaderboard Component
 *
 * Displays top students in a class based on total points earned.
 * Features:
 * - Real-time ranking updates
 * - Highlight current user
 * - Trophy icons for top 3
 * - Responsive layout
 */

import { useState, useEffect } from "react";
import { createClient } from "@/lib/supabase-browser";
import { clientLogger } from "@/lib/client-logger";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface LeaderEntry {
  studentId: string;
  name: string;
  points: number;
  rank: number;
}

interface LeaderboardProps {
  readonly classId: string;
  readonly currentUserId: string;
  readonly limit?: number;
}

const RANK_ICONS = {
  1: "🥇",
  2: "🥈",
  3: "🥉",
} as const;

export function Leaderboard({
  classId,
  currentUserId,
  limit = 10,
}: LeaderboardProps) {
  const [leaders, setLeaders] = useState<LeaderEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchLeaderboard();
  }, [classId]);

  const fetchLeaderboard = async () => {
    try {
      setLoading(true);
      setError(null);
      const supabase = createClient();

      // PERFORMANCE FIX: Use single RPC instead of 3 separate queries
      // Old pattern: enrollments + points + profiles (3 queries)
      // New pattern: Single RPC with JOINs (1 query)
      const { data: leaderboardData, error: leaderboardError } =
        await supabase.rpc("get_class_leaderboard", {
          p_class_id: classId,
          p_limit: limit,
        });

      if (leaderboardError) {
        clientLogger.error(
          "[Leaderboard] Error fetching leaderboard:",
          leaderboardError,
        );
        throw leaderboardError;
      }

      if (!leaderboardData || leaderboardData.length === 0) {
        setLeaders([]);
        setLoading(false);
        return;
      }

      // Transform RPC response to LeaderEntry format
      // Type: GetClassLeaderboardResponse from apps/db/migrations/126_get_class_leaderboard.sql
      const entries: LeaderEntry[] = leaderboardData.map(
        (entry: {
          student_id: string;
          student_name: string;
          total_points: number;
          rank: number;
        }) => ({
          studentId: entry.student_id,
          name: entry.student_name,
          points: Number(entry.total_points),
          rank: entry.rank,
        }),
      );

      setLeaders(entries);
      setLoading(false);
    } catch (err) {
      clientLogger.error(
        "[Leaderboard] Error fetching leaderboard:",
        err instanceof Error ? err : undefined,
      );
      setError("Failed to load leaderboard");
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="space-y-3">
        {[1, 2, 3, 4, 5].map((position) => (
          <div
            key={`position-${position}`}
            className="animate-pulse flex items-center gap-3 p-3 rounded-lg bg-muted"
          >
            <div className="w-8 h-8 bg-muted-foreground/20 rounded-full" />
            <div className="flex-1 space-y-2">
              <div className="h-4 bg-muted-foreground/20 rounded w-1/3" />
              <div className="h-3 bg-muted-foreground/20 rounded w-1/4" />
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-8 text-error">
        <p>{error}</p>
        <button
          onClick={fetchLeaderboard}
          className="mt-2 text-sm text-primary hover:underline"
        >
          Retry
        </button>
      </div>
    );
  }

  if (leaders.length === 0) {
    return (
      <div className="text-center py-8 text-muted-foreground">
        <p>No students have earned points yet.</p>
        <p className="text-sm mt-2">Be the first to complete an assessment!</p>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {leaders.map((leader, index) => {
        const isCurrentUser = leader.studentId === currentUserId;
        const rankIcon = RANK_ICONS[leader.rank as keyof typeof RANK_ICONS];

        return (
          <div
            key={leader.studentId}
            className={`flex items-center gap-3 p-3 rounded-lg transition-all ${
              isCurrentUser
                ? "bg-primary/10 border-2 border-primary"
                : "bg-muted/50 hover:bg-muted"
            }`}
          >
            {/* Rank */}
            <div className="w-8 text-center">
              {rankIcon ? (
                <span className="text-2xl">{rankIcon}</span>
              ) : (
                <span className="text-sm font-bold text-muted-foreground">
                  #{leader.rank}
                </span>
              )}
            </div>

            {/* Name */}
            <div className="flex-1">
              <p
                className={`font-medium ${isCurrentUser ? "text-primary" : "text-text-primary"}`}
              >
                {leader.name}
                {isCurrentUser && (
                  <span className="ml-2 text-xs bg-primary text-white px-2 py-0.5 rounded-full">
                    You
                  </span>
                )}
              </p>
            </div>

            {/* Points */}
            <div className="text-right">
              <p className="font-bold text-warning">
                {leader.points.toLocaleString()}
              </p>
              <p className="text-xs text-muted-foreground">points</p>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/**
 * Compact Leaderboard for Dashboard Widget
 */
export function LeaderboardCompact({
  classId,
  currentUserId,
  limit = 5,
}: LeaderboardProps) {
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center gap-2">
          🏆 Top Students
        </CardTitle>
      </CardHeader>
      <CardContent className="pt-0">
        <Leaderboard
          classId={classId}
          currentUserId={currentUserId}
          limit={limit}
        />
      </CardContent>
    </Card>
  );
}

"use client";

import { useEffect } from "react";
import { clientLogger } from "@/lib/client-logger";

/**
 * BackgroundSyncInitializer
 *
 * Initializes service worker background sync handlers.
 * Must be rendered at app root to ensure sync events are captured.
 *
 * Listens for sync messages from service worker and coordinates
 * with SyncQueue for offline mutation processing.
 */
export function BackgroundSyncInitializer() {
  useEffect(() => {
    if (!("serviceWorker" in navigator)) {
      clientLogger.warn(
        "[BackgroundSyncInitializer] Service Worker not supported",
      );
      return;
    }

    // Register service worker
    navigator.serviceWorker
      .register("/sw.js", { scope: "/" })
      .then((registration) => {
        clientLogger.info(
          "[BackgroundSyncInitializer] Service Worker registered",
          {
            scope: registration.scope,
          },
        );

        // Listen for sync messages from service worker
        navigator.serviceWorker.controller?.postMessage({
          type: "SW_READY",
          timestamp: Date.now(),
        });
      })
      .catch((error) => {
        clientLogger.error(
          "[BackgroundSyncInitializer] Service Worker registration failed",
          error instanceof Error ? error : { error: String(error) },
        );
      });

    // Handle messages from service worker
    const handleMessage = (event: MessageEvent) => {
      if (!event.data) return;

      const { type, tag, timestamp } = event.data;

      clientLogger.debug("[BackgroundSyncInitializer] Message from SW", {
        type,
        tag,
      });

      switch (type) {
        case "BACKGROUND_SYNC":
          // Service worker detected connectivity restored
          // Trigger manual sync in all SyncQueue instances
          globalThis.dispatchEvent(
            new CustomEvent("SW_SYNC_TRIGGERED", { detail: { tag } }),
          );
          break;

        case "SYNC_COMPLETE":
          // Service worker completed sync
          globalThis.dispatchEvent(
            new CustomEvent("SW_SYNC_COMPLETE", { detail: { tag } }),
          );
          break;

        case "PERIODIC_SYNC":
          // Periodic sync triggered
          globalThis.dispatchEvent(
            new CustomEvent("SW_PERIODIC_SYNC", { detail: { tag } }),
          );
          break;

        default:
          break;
      }
    };

    // Listen for service worker messages
    navigator.serviceWorker.addEventListener("message", handleMessage);

    // Cleanup
    return () => {
      navigator.serviceWorker.removeEventListener("message", handleMessage);
    };
  }, []);

  // This component doesn't render anything
  return null;
}

