/**
 * Offline Banner - Full-width notification when offline
 *
 * Features:
 * - Animated slide-in/out
 * - Shows queue count
 * - Auto-hides when back online
 * - Accessible with proper ARIA attributes
 *
 * Best practices from:
 * - https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Guides/Offline_and_background_operation
 */

"use client";

import { useEffect, useState } from "react";
import { WifiOff, Cloud, RefreshCw } from "lucide-react";
import { useNetworkStatus } from "@/hooks/useNetworkStatus";
import { syncQueue, type SyncStatus } from "@/lib/offline/sync-queue";
import { cn } from "@/lib/utils";

interface OfflineBannerProps {
  /** Additional CSS classes */
  readonly className?: string;
  /** Position of the banner */
  readonly position?: "top" | "bottom";
  /** Show pending sync count */
  readonly showPendingCount?: boolean;
}

/**
 * Offline Banner Component
 *
 * Shows a notification when the user is offline.
 * Automatically hides when back online.
 */
export function OfflineBanner({
  className,
  position = "top",
  showPendingCount = true,
}: OfflineBannerProps) {
  const { isOnline, isSlowConnection } = useNetworkStatus();
  const [status, setStatus] = useState<SyncStatus>({
    pendingCount: 0,
    failedCount: 0,
    isSyncing: false,
    lastSyncAt: null,
    lastError: null,
  });
  const [isVisible, setIsVisible] = useState(false);
  const [showSyncingMessage, setShowSyncingMessage] = useState(false);

  // Subscribe to sync status
  useEffect(() => {
    const unsubscribe = syncQueue.subscribe(setStatus);
    return unsubscribe;
  }, []);

  // Handle visibility with animation delay
  useEffect(() => {
    if (!isOnline) {
      setIsVisible(true);
      setShowSyncingMessage(false);
    } else if (status.isSyncing && status.pendingCount > 0) {
      // Show syncing message when coming back online with pending items
      setShowSyncingMessage(true);
      setIsVisible(true);
    } else {
      // Delay hiding for animation
      setShowSyncingMessage(false);
      const timeout = setTimeout(() => setIsVisible(false), 300);
      return () => clearTimeout(timeout);
    }
  }, [isOnline, status.isSyncing, status.pendingCount]);

  // Don't render if not visible and online
  if (!isVisible && isOnline) return null;

  const getMessage = () => {
    if (!isOnline) {
      if (isSlowConnection) {
        return "Slow connection detected. Some features may be limited.";
      }
      if (showPendingCount && status.pendingCount > 0) {
        return `You're offline. ${status.pendingCount} change${status.pendingCount > 1 ? "s" : ""} will sync when you reconnect.`;
      }
      return "You're offline. Changes will sync when you reconnect.";
    }

    if (showSyncingMessage) {
      return `Syncing ${status.pendingCount} change${status.pendingCount > 1 ? "s" : ""}...`;
    }

    return "Back online!";
  };

  const getIcon = () => {
    if (!isOnline) {
      return <WifiOff className="h-4 w-4 flex-shrink-0" />;
    }
    if (showSyncingMessage) {
      return <RefreshCw className="h-4 w-4 flex-shrink-0 animate-spin" />;
    }
    return <Cloud className="h-4 w-4 flex-shrink-0" />;
  };

  const getBackgroundColor = () => {
    if (!isOnline) {
      return "bg-warning";
    }
    if (showSyncingMessage) {
      return "bg-primary";
    }
    return "bg-success";
  };

  return (
    <div
      role="alert"
      aria-live="polite"
      className={cn(
        "fixed left-0 right-0 z-50 transition-all duration-300 ease-in-out",
        position === "top" ? "top-0" : "bottom-0",
        isOnline && !showSyncingMessage
          ? "opacity-0 translate-y-[-100%]"
          : "opacity-100 translate-y-0",
        getBackgroundColor(),
        className,
      )}
    >
      <div className="px-4 py-2 flex items-center justify-center gap-2 text-white">
        {getIcon()}
        <span className="text-sm font-medium">{getMessage()}</span>
      </div>
    </div>
  );
}

/**
 * Inline Offline Notice - Smaller, inline version for cards/sections
 */
export function OfflineNotice({ className }: { className?: string }) {
  const { isOnline } = useNetworkStatus();

  if (isOnline) return null;

  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "flex items-center gap-2 text-warning bg-warning/10 px-3 py-2 rounded-md text-sm",
        className,
      )}
    >
      <WifiOff className="h-4 w-4" />
      <span>Offline mode - changes will sync later</span>
    </div>
  );
}

/**
 * Connection Quality Indicator
 */
export function ConnectionQuality({ className }: { className?: string }) {
  const { isOnline, isSlowConnection, effectiveType } = useNetworkStatus();

  if (!isOnline) {
    return (
      <div
        className={cn("flex items-center gap-1 text-error text-xs", className)}
      >
        <WifiOff className="h-3 w-3" />
        <span>Offline</span>
      </div>
    );
  }

  if (isSlowConnection) {
    return (
      <div
        className={cn(
          "flex items-center gap-1 text-warning text-xs",
          className,
        )}
      >
        <Cloud className="h-3 w-3" />
        <span>Slow ({effectiveType})</span>
      </div>
    );
  }

  return null; // Don't show anything for good connections
}

/**
 * Sync Status Indicator - Visual sync status for offline-first UX
 *
 * Features:
 * - Shows online/offline status
 * - Displays pending sync count
 * - Manual sync button
 * - Last sync time tooltip
 *
 * Best practices from:
 * - https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Guides/Offline_and_background_operation
 */

"use client";

import { useEffect, useState, useCallback } from "react";
import { Wifi, WifiOff, RefreshCw, Check, AlertCircle } from "lucide-react";
import { useNetworkStatus } from "@/hooks/useNetworkStatus";
import { syncQueue, type SyncStatus } from "@/lib/offline/sync-queue";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
  TooltipProvider,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

interface SyncStatusIndicatorProps {
  /** Additional CSS classes */
  readonly className?: string;
  /** Show pending count badge */
  readonly showBadge?: boolean;
  /** Compact mode (icon only) */
  readonly compact?: boolean;
}

/**
 * Format relative time (e.g., "2 min ago")
 */
function formatRelativeTime(timestamp: number): string {
  const seconds = Math.floor((Date.now() - timestamp) / 1000);

  if (seconds < 60) return "Just now";
  if (seconds < 3600) return `${Math.floor(seconds / 60)} min ago`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)} hr ago`;
  return `${Math.floor(seconds / 86400)} days ago`;
}

/**
 * Sync Status Indicator Component
 *
 * Shows the current sync status with:
 * - Green checkmark: All synced
 * - Yellow spinning: Syncing in progress
 * - Yellow with badge: Pending items to sync
 * - Red wifi-off: Offline
 * - Red alert: Sync errors
 */
export function SyncStatusIndicator({
  className,
  showBadge = true,
  compact = false,
}: SyncStatusIndicatorProps) {
  const { isOnline } = useNetworkStatus();
  const [status, setStatus] = useState<SyncStatus>({
    pendingCount: 0,
    failedCount: 0,
    isSyncing: false,
    lastSyncAt: null,
    lastError: null,
  });
  const [isManualSyncing, setIsManualSyncing] = useState(false);

  // Subscribe to sync status updates
  useEffect(() => {
    const unsubscribe = syncQueue.subscribe((newStatus) => {
      setStatus(newStatus);
    });
    return unsubscribe;
  }, []);

  // Handle manual sync
  const handleManualSync = useCallback(async () => {
    if (!isOnline || isManualSyncing) return;

    setIsManualSyncing(true);
    try {
      await syncQueue.manualSync();
    } finally {
      setIsManualSyncing(false);
    }
  }, [isOnline, isManualSyncing]);

  // Determine icon and color
  const getStatusDisplay = () => {
    if (!isOnline) {
      return {
        icon: <WifiOff className="h-4 w-4" />,
        color: "text-error",
        label: "Offline - changes will sync when you reconnect",
      };
    }

    if (status.isSyncing || isManualSyncing) {
      return {
        icon: <RefreshCw className="h-4 w-4 animate-spin" />,
        color: "text-warning",
        label: "Syncing...",
      };
    }

    if (status.failedCount > 0) {
      return {
        icon: <AlertCircle className="h-4 w-4" />,
        color: "text-error",
        label: `${status.failedCount} failed - tap to retry`,
      };
    }

    if (status.pendingCount > 0) {
      return {
        icon: <RefreshCw className="h-4 w-4" />,
        color: "text-warning",
        label: `${status.pendingCount} pending - tap to sync`,
      };
    }

    return {
      icon: <Check className="h-4 w-4" />,
      color: "text-success",
      label: status.lastSyncAt
        ? `All synced (${formatRelativeTime(status.lastSyncAt)})`
        : "All synced",
    };
  };

  const { icon, color, label } = getStatusDisplay();
  const canSync =
    isOnline &&
    !status.isSyncing &&
    !isManualSyncing &&
    status.pendingCount > 0;
  const hasBadge = showBadge && status.pendingCount > 0 && !status.isSyncing;

  if (compact) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <div
              className={cn(
                "relative inline-flex items-center justify-center",
                className,
              )}
            >
              <span className={color}>{icon}</span>
              {hasBadge && (
                <span className="absolute -top-1 -right-1 bg-warning text-warning-foreground text-[10px] rounded-full h-4 w-4 flex items-center justify-center font-medium">
                  {status.pendingCount > 9 ? "9+" : status.pendingCount}
                </span>
              )}
            </div>
          </TooltipTrigger>
          <TooltipContent side="bottom">
            <p>{label}</p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="ghost"
            size="sm"
            className={cn("relative", className)}
            onClick={canSync ? handleManualSync : undefined}
            disabled={!canSync && status.pendingCount > 0}
          >
            <span className={color}>{icon}</span>
            {hasBadge && (
              <span className="absolute -top-1 -right-1 bg-warning text-warning-foreground text-[10px] rounded-full h-4 w-4 flex items-center justify-center font-medium">
                {status.pendingCount > 9 ? "9+" : status.pendingCount}
              </span>
            )}
          </Button>
        </TooltipTrigger>
        <TooltipContent side="bottom">
          <p>{label}</p>
          {status.lastError && (
            <p className="text-error text-xs mt-1">Error: {status.lastError}</p>
          )}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

/**
 * Hook to get sync status for custom UI
 */
export function useSyncStatus() {
  const { isOnline } = useNetworkStatus();
  const [status, setStatus] = useState<SyncStatus>({
    pendingCount: 0,
    failedCount: 0,
    isSyncing: false,
    lastSyncAt: null,
    lastError: null,
  });

  useEffect(() => {
    const unsubscribe = syncQueue.subscribe(setStatus);
    return unsubscribe;
  }, []);

  return {
    ...status,
    isOnline,
    canSync: isOnline && !status.isSyncing && status.pendingCount > 0,
    sync: () => syncQueue.manualSync(),
  };
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { RefreshCw } from "lucide-react";
import {
  validateEmail,
  validatePassword,
  validatePasswordMatch,
} from "@/lib/validation-utils";
import { OTP_LENGTH } from "@/lib/auth-constants";
import type { UseOTPInputReturn } from "@/hooks/useOTPInput";
import { requestOtp } from "@/app/actions/auth";
import { createClient } from "@/lib/supabase-browser";
import { authLogger } from "@/lib/auth-logger";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import type { AuthState, AuthActions } from "@/hooks/useAuthState";
import { formatTimeTidyCompact } from "@/lib/time-utils";

/**
 * ATAL AI Student Sign Up (Email) - Jyoti Theme
 *
 * Design Rules Applied:
 * - Primary button with correct shadows
 * - Error text: text-error
 * - Links: text-primary
 * - Muted text: text-text-muted
 */

const RESEND_COOLDOWN_SECONDS = 60;

interface SignUpEmailFlowProps {
  readonly state: AuthState;
  readonly actions: AuthActions;
  readonly otpInput: UseOTPInputReturn;
  readonly isLoading: boolean;
  readonly onSuccess: () => void;
}

export function SignUpEmailFlow({
  state,
  actions,
  otpInput,
  isLoading,
  onSuccess,
}: SignUpEmailFlowProps) {
  const router = useRouter();
  const supabase = createClient();
  const [resendCooldown, setResendCooldown] = useState(0);
  const [isResending, setIsResending] = useState(false);

  // Start cooldown timer when OTP is sent
  useEffect(() => {
    if (state.signupEmailOtpSent && resendCooldown === 0) {
      setResendCooldown(RESEND_COOLDOWN_SECONDS);
    }
  }, [state.signupEmailOtpSent]);

  // Countdown timer
  useEffect(() => {
    if (resendCooldown > 0) {
      const timer = setTimeout(() => {
        setResendCooldown(resendCooldown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [resendCooldown]);

  const handleResendOtp = useCallback(async () => {
    if (resendCooldown > 0 || isResending) return;

    setIsResending(true);
    try {
      const result = await requestOtp(state.signupEmailAddress.trim());
      if (result.success) {
        toast.success("OTP resent to your email!");
        setResendCooldown(RESEND_COOLDOWN_SECONDS);
      } else {
        toast.error(result.error || "Failed to resend OTP");
      }
    } catch (error) {
      toast.error("Failed to resend OTP");
    } finally {
      setIsResending(false);
    }
  }, [resendCooldown, isResending, state.signupEmailAddress]);

  async function handleSignUpEmailSendOtp(e: React.FormEvent) {
    e.preventDefault();
    actions.setIsLoading(true);
    actions.setSignupEmailError(null);

    // Validate email
    const emailValidation = validateEmail(state.signupEmailAddress);
    if (!emailValidation.valid) {
      actions.setSignupEmailError(emailValidation.error || "Invalid email");
      actions.setIsLoading(false);
      return;
    }

    try {
      const result = await requestOtp(state.signupEmailAddress.trim());
      if (!result.success) {
        // SECURITY FIX: Don't differentiate email enumeration responses
        // All error responses are generic for security (prevents email enumeration attacks)
        // The generic error message already suggests checking inbox or creating account
        authLogger.debug("[SignUp Email] OTP request failed", {
          error: result.error,
        });
        actions.setSignupEmailError(
          result.error ||
            "Failed to send OTP. If this email is registered, check your inbox for a login link.",
        );
        toast.error(
          result.error ||
            "Failed to send OTP. If this email is registered, check your inbox for a login link.",
        );
      } else {
        toast.success("OTP sent to your email!");
        actions.setSignupEmailOtpSent(true);
      }
    } catch (error) {
      authLogger.error("[SignUp Email] Failed to send OTP", error);
      actions.setSignupEmailError("Failed to send OTP");
      toast.error("Failed to send OTP");
    } finally {
      actions.setIsLoading(false);
    }
  }

  async function handleSignUpEmailVerifyAndCreate(e: React.FormEvent) {
    e.preventDefault();
    actions.setIsLoading(true);
    actions.setSignupEmailError(null);

    // Validate inputs
    const passwordValidation = validatePassword(state.signupEmailPassword);
    if (!passwordValidation.valid) {
      actions.setSignupEmailError(
        passwordValidation.errors.join(", ") || "Invalid password",
      );
      actions.setIsLoading(false);
      return;
    }

    const matchValidation = validatePasswordMatch(
      state.signupEmailPassword,
      state.signupEmailPasswordConfirm,
    );
    if (!matchValidation.valid) {
      actions.setSignupEmailError(
        matchValidation.error || "Passwords do not match",
      );
      actions.setIsLoading(false);
      return;
    }

    try {
      // Verify OTP and create account
      const { data, error } = await supabase.auth.verifyOtp({
        email: state.signupEmailAddress,
        token: otpInput.value,
        type: "email",
      });

      if (error) {
        authLogger.error("[SignUp Email] Verification failed", error);
        actions.setSignupEmailError(error.message || "Failed to verify OTP");
        toast.error(error.message || "OTP verification failed");
        return;
      }

      if (!data.user) {
        actions.setSignupEmailError("Verification failed");
        toast.error("Email verification failed");
        return;
      }

      // Set password
      const { error: updateError } = await supabase.auth.updateUser({
        password: state.signupEmailPassword,
      });

      if (updateError) {
        authLogger.error("[SignUp Email] Failed to set password", updateError);
        actions.setSignupEmailError("Failed to set password");
        toast.error("Failed to set password");
        return;
      }

      toast.success("Account created successfully! 🎉");
      actions.resetSignupEmail();
      onSuccess();
      router.push("/app/dashboard");
    } catch (error) {
      authLogger.error("[SignUp Email] Unexpected error", error);
      actions.setSignupEmailError("An unexpected error occurred");
      toast.error("An unexpected error occurred");
    } finally {
      actions.setIsLoading(false);
    }
  }

  // Send OTP step
  if (!state.signupEmailOtpSent) {
    return (
      <form onSubmit={handleSignUpEmailSendOtp} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="signup-email" className="text-text">
            Email Address
          </Label>
          <Input
            id="signup-email"
            type="email"
            placeholder="your.email@example.com"
            value={state.signupEmailAddress}
            onChange={(e) => actions.setSignupEmailAddress(e.target.value)}
            required
            disabled={isLoading}
          />
          {state.signupEmailError && (
            <p className="text-sm text-error">{state.signupEmailError}</p>
          )}
        </div>

        <Button
          type="submit"
          className="w-full text-[17px]"
          disabled={isLoading || !state.signupEmailAddress}
          loading={isLoading}
        >
          Send OTP
          <span className="ml-2">→</span>
        </Button>
      </form>
    );
  }

  // Verify OTP & create account step
  return (
    <form onSubmit={handleSignUpEmailVerifyAndCreate} className="space-y-4">
      <div className="space-y-2">
        <Label htmlFor="signup-email-otp" className="text-text">
          Verification Code
        </Label>
        <Input
          id="signup-email-otp"
          type="text"
          placeholder="123456"
          value={otpInput.value}
          onChange={(e) => otpInput.onChange(e.target.value)}
          required
          disabled={isLoading}
          maxLength={OTP_LENGTH}
          className="text-center text-2xl font-mono tracking-widest"
        />
        <p className="text-xs text-text-muted">
          Enter the 6-digit code sent to your email
        </p>
      </div>

      <div className="space-y-2">
        <Label htmlFor="signup-email-password" className="text-text">
          Password
        </Label>
        <Input
          id="signup-email-password"
          type="password"
          placeholder="Minimum 8 characters"
          value={state.signupEmailPassword}
          onChange={(e) => actions.setSignupEmailPassword(e.target.value)}
          required
          disabled={isLoading}
        />
      </div>

      <div className="space-y-2">
        <Label htmlFor="signup-email-password-confirm" className="text-text">
          Confirm Password
        </Label>
        <Input
          id="signup-email-password-confirm"
          type="password"
          placeholder="Re-enter your password"
          value={state.signupEmailPasswordConfirm}
          onChange={(e) =>
            actions.setSignupEmailPasswordConfirm(e.target.value)
          }
          required
          disabled={isLoading}
        />
        {state.signupEmailError && (
          <p className="text-sm text-error">{state.signupEmailError}</p>
        )}
      </div>

      <Button
        type="submit"
        className="w-full text-[17px]"
        disabled={
          isLoading ||
          otpInput.value.length !== OTP_LENGTH ||
          !state.signupEmailPassword ||
          !state.signupEmailPasswordConfirm
        }
        loading={isLoading}
      >
        Create Account
        <span className="ml-2">→</span>
      </Button>

      {/* Resend OTP Button with Timer */}
      <div className="flex items-center justify-center">
        <button
          type="button"
          onClick={handleResendOtp}
          disabled={isLoading || isResending || resendCooldown > 0}
          className={`flex items-center gap-2 text-sm transition-colors ${
            resendCooldown > 0 || isResending
              ? "text-text-muted cursor-not-allowed"
              : "text-primary hover:text-primary-dark hover:underline"
          }`}
        >
          <RefreshCw
            className={`h-4 w-4 ${isResending ? "animate-spin" : ""}`}
          />
          {isResending
            ? "Sending..."
            : resendCooldown > 0
              ? `Resend OTP in ${formatTimeTidyCompact(resendCooldown)}`
              : "Resend OTP"}
        </button>
      </div>

      <button
        type="button"
        onClick={() => {
          actions.setSignupEmailOtpSent(false);
          otpInput.reset();
        }}
        className="text-sm text-text-secondary hover:text-primary hover:underline block w-full text-center transition-colors"
        disabled={isLoading}
      >
        Change email
      </button>
    </form>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { enrollStudent } from "@/app/actions/teacher";

interface InviteStudentDialogProps {
  readonly classId: string;
}

interface StudentResult {
  id: string;
  email: string;
}

export function InviteStudentDialog({ classId }: InviteStudentDialogProps) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [searchInput, setSearchInput] = useState("");
  const [studentId, setStudentId] = useState("");
  const [selectedStudent, setSelectedStudent] = useState<StudentResult | null>(
    null,
  );
  const [searchResults, setSearchResults] = useState<StudentResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [searching, setSearching] = useState(false);

  async function handleSearch() {
    if (!searchInput.trim()) {
      setSearchResults([]);
      return;
    }

    setSearching(true);
    try {
      // Search for students by email or ID (using API route)
      const response = await fetch("/api/teacher/search-students", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: searchInput }),
      });

      if (response.ok) {
        const { students } = await response.json();
        setSearchResults(students);
      } else {
        toast.error("Failed to search students");
      }
    } catch {
      toast.error("An error occurred while searching");
    } finally {
      setSearching(false);
    }
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    if (!studentId) {
      toast.error("Please select a student");
      return;
    }

    setLoading(true);

    try {
      const result = await enrollStudent(classId, studentId);

      if (result.success) {
        toast.success("Student enrolled successfully!");
        setStudentId("");
        setSearchInput("");
        setSelectedStudent(null);
        setSearchResults([]);
        setOpen(false);
        router.refresh();
      } else if ("error" in result) {
        toast.error(result.error || "Failed to enroll student");
      } else {
        toast.error("Failed to enroll student");
      }
    } catch {
      toast.error("An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <span className="mr-2">+</span>
          Invite Student
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-md">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Invite Student to Class</DialogTitle>
            <DialogDescription>
              Search and add students to your class by email or ID
            </DialogDescription>
          </DialogHeader>

          <div className="py-4 space-y-4">
            {/* Search Input */}
            <div className="space-y-2">
              <Label htmlFor="search-student">Search by Email or User ID</Label>
              <div className="flex gap-2">
                <Input
                  id="search-student"
                  placeholder="student@example.com or user ID"
                  value={searchInput}
                  onChange={(e) => {
                    setSearchInput(e.target.value);
                    if (e.target.value.trim()) {
                      handleSearch();
                    } else {
                      setSearchResults([]);
                    }
                  }}
                  disabled={loading || searching}
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleSearch}
                  disabled={loading || searching || !searchInput.trim()}
                  className="px-4"
                >
                  {searching ? "..." : "Search"}
                </Button>
              </div>
              <p className="text-xs text-text-secondary">
                Enter student email or user ID to find them
              </p>
            </div>

            {/* Search Results */}
            {searchResults.length > 0 && (
              <div className="space-y-2">
                <Label htmlFor="student-list" className="text-sm font-medium">
                  Select Student
                </Label>
                <ul
                  id="student-list"
                  className="border rounded-lg space-y-1 max-h-48 overflow-y-auto"
                  role="listbox"
                  aria-label="Student search results"
                >
                  {searchResults.map((student) => (
                    <li key={student.id} role="option">
                      <button
                        type="button"
                        onClick={() => {
                          setStudentId(student.id);
                          setSelectedStudent(student);
                          setSearchResults([]);
                          setSearchInput("");
                        }}
                        className="w-full text-left px-3 py-2 hover:bg-primary/10 border-b last:border-b-0 transition-colors focus:outline-none focus:ring-2 focus:ring-primary"
                        aria-label={`Select student: ${student.email} (ID: ${student.id})`}
                      >
                        <p className="font-medium text-sm">{student.email}</p>
                        <p className="text-xs text-text-secondary">
                          {student.id}
                        </p>
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Selected Student Info */}
            {selectedStudent && (
              <div className="p-3 bg-cyan-lightest border border-cyan/30 rounded-lg">
                <p className="text-sm font-medium text-cyan-darkest">
                  Selected Student:
                </p>
                <p className="text-sm text-cyan-darkest">
                  {selectedStudent.email}
                </p>
                <p className="text-xs text-cyan-dark mt-1">
                  {selectedStudent.id}
                </p>
              </div>
            )}

            {/* Manual ID Entry */}
            {!selectedStudent && (
              <div className="space-y-2">
                <Label htmlFor="manual-id" className="text-xs">
                  Or enter Student ID manually
                </Label>
                <Input
                  id="manual-id"
                  placeholder="00000000-0000-0000-0000-000000000002"
                  value={studentId}
                  onChange={(e) => setStudentId(e.target.value)}
                  disabled={loading || searching}
                  className="text-sm"
                />
              </div>
            )}
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setOpen(false);
                setSearchInput("");
                setStudentId("");
                setSelectedStudent(null);
                setSearchResults([]);
              }}
              disabled={loading}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={loading || !studentId}>
              {loading ? "Enrolling..." : "Enroll Student"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

/**
 * Real-time Student Progress Grid
 *
 * Shows all enrolled students' progress with live updates.
 * Uses Supabase real-time subscriptions for instant visibility.
 *
 * Features:
 * - Real-time mastery score updates
 * - At-risk student highlighting
 * - Activity status indicators
 * - Click to view detailed progress
 */

import { useEffect, useState, useCallback } from "react";
import { createClient } from "@/lib/supabase-browser";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { clientLogger } from "@/lib/client-logger";

interface StudentProgress {
  id: string;
  student_id: string;
  student_name: string;
  email: string;
  module_id: string;
  topics_mastered: number;
  total_topics: number;
  average_mastery: number;
  last_activity: string | null;
  is_at_risk: boolean;
  current_topic?: string;
}

interface StudentProgressGridProps {
  readonly classId: string;
  readonly teacherId: string;
}

export function StudentProgressGrid({
  classId,
  teacherId,
}: StudentProgressGridProps) {
  const [students, setStudents] = useState<StudentProgress[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch initial student data
  const fetchStudentProgress = useCallback(async () => {
    try {
      const supabase = createClient();

      // Get all enrolled students with their progress
      const { data, error: fetchError } = await supabase
        .from("enrollments")
        .select(
          `
          student_id,
          student:auth_users_view!enrollments_student_id_fkey (
            id,
            email,
            raw_user_meta_data
          )
        `,
        )
        .eq("class_id", classId);

      if (fetchError) throw fetchError;

      // Get knowledge state for each student
      const studentIds = data?.map((e) => e.student_id) || [];

      if (studentIds.length === 0) {
        setStudents([]);
        setLoading(false);
        return;
      }

      // PERFORMANCE FIX: Use RPC for database aggregation instead of client-side filtering
      // Old pattern: Fetch all rows, filter in JS (O(n²))
      // New pattern: Database GROUP BY aggregation (O(n log n))
      const { data: progressData, error: progressError } = await supabase.rpc(
        "get_class_student_progress",
        { p_student_ids: studentIds },
      );

      if (progressError) {
        clientLogger.error(
          "[StudentProgressGrid] Error fetching progress:",
          progressError,
        );
        throw progressError;
      }

      // Create map for quick lookup
      const progressMap = new Map<string, StudentProgress>();

      for (const enrollment of data || []) {
        const studentId = enrollment.student_id;
        // The join returns an array of student objects
        const studentArray = enrollment.student as Array<{
          id: string;
          email: string;
          raw_user_meta_data?: { full_name?: string };
        }> | null;
        const studentData = studentArray?.[0] || null;

        // Find progress data for this student from RPC results
        // Type: GetClassStudentProgressResponse from apps/db/migrations/124_get_class_student_progress.sql
        const progress = progressData?.find(
          (p: {
            student_id: string;
            student_name: string;
            total_topics: number;
            topics_mastered: number;
            avg_mastery_score: number;
            last_activity: string | null;
          }) => p.student_id === studentId,
        );

        const masteredTopics = progress?.topics_mastered || 0;
        const totalTopics = progress?.topics_total || 0;
        const avgMastery = progress?.avg_mastery_score || 0;
        const latestActivity = progress?.last_activity || null;

        // Check if at-risk (low average mastery)
        const isAtRisk = avgMastery < 40 && totalTopics > 0;

        progressMap.set(studentId, {
          id: `${studentId}-progress`,
          student_id: studentId,
          student_name:
            studentData?.raw_user_meta_data?.full_name ||
            studentData?.email?.split("@")[0] ||
            "Unknown Student",
          email: studentData?.email || "",
          module_id: "all",
          topics_mastered: masteredTopics,
          total_topics: 50, // 5 modules x 10 topics
          average_mastery: Math.round(avgMastery * 100) / 100,
          last_activity: latestActivity,
          is_at_risk: isAtRisk,
        });
      }

      setStudents(Array.from(progressMap.values()));
      setLoading(false);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      clientLogger.error("[StudentProgressGrid] Error: " + errorMessage);
      setError("Failed to load student progress");
      setLoading(false);
    }
  }, [classId]);

  // Set up real-time subscription
  useEffect(() => {
    fetchStudentProgress();

    const supabase = createClient();

    // Subscribe to knowledge state changes
    const channel = supabase
      .channel(`class-progress-${classId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "student_knowledge_state",
        },
        () => {
          // Refetch when any progress changes
          // In a production app, we'd do smarter updates
          fetchStudentProgress();
        },
      )
      .subscribe();

    return () => {
      channel.unsubscribe();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [classId]); // Only depend on classId to avoid subscription recreation

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {[1, 2, 3, 4, 5, 6].map((i) => (
          <Card key={`progress-skeleton-${i}`} className="animate-pulse">
            <CardContent className="p-4">
              <div className="h-4 bg-muted rounded w-3/4 mb-2" />
              <div className="h-3 bg-muted rounded w-1/2" />
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-8 text-error">
        <p>{error}</p>
      </div>
    );
  }

  if (students.length === 0) {
    return (
      <div className="text-center py-8 text-muted-foreground">
        <p>No students enrolled in this class yet.</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
      {students.map((student) => (
        <StudentProgressCard key={student.id} student={student} />
      ))}
    </div>
  );
}

/**
 * Individual Student Progress Card
 */
function StudentProgressCard({
  student,
}: {
  readonly student: StudentProgress;
}) {
  const progressPercent = Math.round(
    (student.topics_mastered / student.total_topics) * 100,
  );

  const getActivityStatus = (lastActivity: string | null) => {
    if (!lastActivity) return { status: "inactive", label: "No activity" };

    const hours = Math.floor(
      (Date.now() - new Date(lastActivity).getTime()) / (1000 * 60 * 60),
    );

    if (hours < 1) return { status: "active", label: "Active now" };
    if (hours < 24) return { status: "recent", label: `${hours}h ago` };
    if (hours < 168)
      return { status: "week", label: `${Math.floor(hours / 24)}d ago` };
    return { status: "inactive", label: "Over a week" };
  };

  const activity = getActivityStatus(student.last_activity);

  return (
    <Card
      className={`transition-all hover:shadow-md ${
        student.is_at_risk ? "border-destructive/50 bg-destructive/10" : ""
      }`}
    >
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium truncate">
            {student.student_name}
          </CardTitle>
          <span
            className={`w-2 h-2 rounded-full ${
              activity.status === "active"
                ? "bg-success"
                : activity.status === "recent"
                  ? "bg-warning"
                  : "bg-muted"
            }`}
            title={activity.label}
          />
        </div>
        <p className="text-xs text-muted-foreground truncate">
          {student.email}
        </p>
      </CardHeader>
      <CardContent className="pt-0">
        {/* Progress Bar */}
        <div className="mb-2">
          <div className="flex justify-between text-xs mb-1">
            <span>Progress</span>
            <span>{progressPercent}%</span>
          </div>
          <div className="h-2 bg-muted rounded-full overflow-hidden">
            <div
              className={`h-full transition-all ${
                student.is_at_risk
                  ? "bg-destructive"
                  : progressPercent >= 70
                    ? "bg-success"
                    : progressPercent >= 40
                      ? "bg-warning"
                      : "bg-primary"
              }`}
              style={{ width: `${progressPercent}%` }}
            />
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 gap-2 text-xs">
          <div>
            <span className="text-muted-foreground">Mastered:</span>{" "}
            <span className="font-medium">
              {student.topics_mastered}/{student.total_topics}
            </span>
          </div>
          <div>
            <span className="text-muted-foreground">Avg:</span>{" "}
            <span className="font-medium">{student.average_mastery}%</span>
          </div>
        </div>

        {/* At-Risk Badge */}
        {student.is_at_risk && (
          <div className="mt-2 text-xs text-destructive font-medium flex items-center gap-1">
            <span>⚠️</span> Needs attention
          </div>
        )}

        {/* Activity */}
        <div className="mt-2 text-xs text-muted-foreground">
          {activity.label}
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { motion, HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

// Extend Window interface for test environment detection
declare global {
  interface Window {
    __PLAYWRIGHT_TEST__?: boolean;
  }
  interface Global {
    __PLAYWRIGHT__?: boolean;
  }
}

// Detect test environment for Playwright test stability
// Uses runtime detection to check if we're in a test/Playwright browser
const isTestEnvironment = () => {
  if (typeof globalThis === "undefined") return false;

  // Check multiple ways to detect test environment
  return (
    // Standard test env variables
    process.env.NODE_ENV === "test" ||
    process.env.PLAYWRIGHT_TEST === "true" ||
    // Playwright detection - check if running in test mode
    (typeof navigator !== "undefined" &&
      (navigator.webdriver === true ||
        navigator.userAgent.includes("HeadlessChrome") ||
        // Check for test globals
        (globalThis as any).__PLAYWRIGHT_TEST__ === true)) ||
    // Check for test globals that might be set
    (typeof globalThis !== "undefined" &&
      (globalThis as any).__PLAYWRIGHT__ === true)
  );
};

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-lg text-sm font-medium transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 relative overflow-hidden",
  {
    variants: {
      variant: {
        default:
          "bg-gradient-to-br from-primary to-primary-light text-white shadow-md hover:shadow-lg border-2 border-white/20",
        destructive:
          "bg-error text-white hover:bg-error/90 shadow-md border-2 border-white/20",
        outline:
          "border-2 border-primary bg-white text-primary hover:bg-surface",
        secondary:
          "bg-surface text-text-primary hover:bg-border border-2 border-border",
        ghost:
          "hover:bg-surface hover:text-primary border-2 border-transparent",
        link: "text-primary underline-offset-4 hover:underline",
        gradient:
          "bg-gradient-to-br from-primary to-primary-light text-white shadow-md hover:shadow-lg border-2 border-white/20",
      },
      size: {
        default: "h-11 px-6 py-2.5",
        sm: "h-9 rounded-md px-4 text-xs",
        lg: "h-12 rounded-lg px-8 text-base",
        icon: "h-11 w-11",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export interface ButtonProps
  extends
    Omit<HTMLMotionProps<"button">, "ref" | "children">,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  loading?: boolean;
  children?: React.ReactNode;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      loading = false,
      children,
      disabled,
      ...props
    },
    ref,
  ) => {
    const Comp = asChild ? Slot : motion.button;
    const inTestMode = isTestEnvironment();

    return (
      <Comp
        ref={ref}
        className={cn(buttonVariants({ variant, size, className }))}
        whileHover={inTestMode ? undefined : { scale: 1.02 }}
        whileTap={inTestMode ? undefined : { scale: 0.98 }}
        transition={
          inTestMode
            ? undefined
            : { type: "spring", stiffness: 400, damping: 17 }
        }
        disabled={disabled || loading}
        {...(props as Record<string, unknown>)}
      >
        {loading && !inTestMode && (
          <motion.div
            className="absolute inset-0 flex items-center justify-center bg-gradient-to-br from-primary/90 to-primary-light/90"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div
              className="h-5 w-5 rounded-full border-2 border-white border-t-transparent"
              animate={{ rotate: 360 }}
              transition={{ duration: 0.8, repeat: Infinity, ease: "linear" }}
            />
          </motion.div>
        )}
        {children}
      </Comp>
    );
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };

"use client";

import React, { ReactNode, InputHTMLAttributes } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeSanitize from "rehype-sanitize";
import rehypeRaw from "rehype-raw";

interface MarkdownRendererProps {
  readonly content: string;
  readonly className?: string;
}

// React Markdown component prop types
interface CodeProps {
  readonly node?: unknown;
  readonly inline?: boolean;
  readonly className?: string;
  readonly children?: ReactNode;
}

interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  readonly node?: unknown;
}

/**
 * Secure markdown renderer with GitHub Flavored Markdown support
 * - XSS protection via rehype-sanitize
 * - Supports tables, strikethrough, task lists (GFM)
 * - Theming via CSS variables (dark mode support)
 * - Accessibility: semantic HTML maintained
 */
export function MarkdownRenderer({
  content,
  className,
}: MarkdownRendererProps) {
  return (
    <div
      className={className || "prose prose-slate dark:prose-invert max-w-none"}
    >
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[rehypeRaw, rehypeSanitize]}
        components={{
          // Headings with semantic sizing and primary color
          h1: ({ node, ...props }) => (
            <h1
              className="text-3xl font-bold mb-4 text-primary leading-tight"
              {...props}
            />
          ),
          h2: ({ node, ...props }) => (
            <h2
              className="text-2xl font-semibold mb-3 text-primary leading-tight mt-6"
              {...props}
            />
          ),
          h3: ({ node, ...props }) => (
            <h3
              className="text-xl font-semibold mb-2 text-primary leading-tight mt-4"
              {...props}
            />
          ),
          h4: ({ node, ...props }) => (
            <h4
              className="text-lg font-semibold mb-2 leading-tight mt-3"
              {...props}
            />
          ),
          h5: ({ node, ...props }) => (
            <h5
              className="text-base font-semibold mb-2 leading-tight mt-2"
              {...props}
            />
          ),
          h6: ({ node, ...props }) => (
            <h6
              className="text-sm font-semibold mb-2 text-muted-foreground leading-tight mt-2"
              {...props}
            />
          ),

          // Paragraph with proper spacing
          p: ({ node, ...props }) => (
            <p className="mb-4 leading-7 text-foreground" {...props} />
          ),

          // Lists with proper indentation
          ul: ({ node, ...props }) => (
            <ul
              className="list-disc list-inside mb-4 space-y-2 text-foreground"
              {...props}
            />
          ),
          ol: ({ node, ...props }) => (
            <ol
              className="list-decimal list-inside mb-4 space-y-2 text-foreground"
              {...props}
            />
          ),
          li: ({ node, ...props }) => (
            <li className="ml-2 leading-7" {...props} />
          ),

          // Code with syntax highlighting background
          code: (props: CodeProps) => {
            const { node, inline, ...rest } = props;
            return inline ? (
              <code
                className="bg-muted px-1.5 py-0.5 rounded text-sm font-mono text-error dark:text-error/80 break-words"
                {...rest}
              />
            ) : (
              <pre className="bg-muted border border-border rounded-lg overflow-x-auto p-4 mb-4">
                <code
                  className="font-mono text-sm text-foreground block"
                  {...rest}
                />
              </pre>
            );
          },

          // Links with accessible styling
          a: ({ node, ...props }) => (
            <a
              className="text-primary hover:text-primary/80 underline underline-offset-2 break-words"
              target="_blank"
              rel="noopener noreferrer"
              {...props}
            />
          ),

          // Blockquotes with left border
