        if (result.success) {
          toast.success("Password reset successfully! ✓");
          // Reset form and go back to login
          resetForgotPassword();
          setStep("login");
          setLoginEmail(state.forgotEmail);
        } else {
          toast.error(result.error || "Failed to reset password");
