          setLoading(false);
          return;
        }

        const matchValidation = validatePasswordMatch(
          state.password,
          state.passwordConfirm,
        );
        if (!matchValidation.valid) {
          toast.error(matchValidation.error || "Passwords do not match");
          setLoading(false);
          return;
