}

import { authLogger } from "@/lib/auth-logger";

// FEATURE FLAG: Set to false to disable caching globally (emergency disable)
const CACHE_ENABLED = process.env.ENABLE_QUERY_CACHE !== "false"; // Default: enabled

/**
 * Cache entry with metadata
 */
interface CacheEntry<T> {
  data: T;
  timestamp: number;
  ttl: number;
}

/**
 * Query cache metrics for monitoring
 */
interface CacheMetrics {
  hits: number;
  misses: number;
  size: number;
  maxSize: number;
  utilizationPercent: number;
}

/**
 * In-memory LRU (Least Recently Used) cache for database query results
 * Server-side only - integrates with existing auth-logger pattern
 *
 * Thread-safe: Safe for concurrent reads/writes
 * Memory-bounded: Max 500 entries to prevent memory leaks
 * TTL-aware: Entries expire based on configured TTL
 * Feature-flag: Can be disabled globally via ENABLE_QUERY_CACHE env var
 *
 * @example
 * ```typescript
 * const results = await queryCache.getOrFetch(
 *   'admin:dashboard:stats',
 *   async () => {
 *     const [teachers, students] = await Promise.all([...]);
 *     return { totalTeachers: teachers.length, totalStudents: students.length };
 *   },
 *   5 * 60 * 1000 // 5 minutes
 * );
 * ```
 */
export class QueryCache {
  private cache = new Map<string, CacheEntry<any>>();
  private maxSize = 500;
  private metrics = {
    hits: 0,
    misses: 0,
  };

  /**
   * Get cached value or fetch fresh data
   * @param key - Cache key (use pattern: 'resource:id:operation')
   * @param fetcher - Async function that fetches fresh data
   * @param ttl - Time-to-live in milliseconds (default: 5 minutes)
   * @returns Cached or fresh data
   */
  async getOrFetch<T>(
    key: string,
    fetcher: () => Promise<T>,
    ttl: number = 5 * 60 * 1000, // 5 minutes default
  ): Promise<T> {
    // Check if caching is disabled via feature flag
    if (!CACHE_ENABLED) {
      authLogger.debug("Query cache disabled by feature flag", { key });
      return await fetcher();
    }

    // Check if entry exists and is not expired
    const cached = this.cache.get(key);
    if (cached && Date.now() - cached.timestamp < cached.ttl) {
      this.metrics.hits++;
      authLogger.debug("Cache hit", {
        key,
        age: `${Date.now() - cached.timestamp}ms`,
        hitRatio: `${this.getHitRatio().toFixed(1)}%`,
      });
      return cached.data as T;
    }

    // Cache miss - fetch fresh data
    this.metrics.misses++;
    authLogger.debug("Cache miss - fetching fresh data", { key });

    try {
      const data = await fetcher();

      // Enforce max size with LRU eviction (remove oldest entry)
      if (this.cache.size >= this.maxSize) {
        const firstKey = this.cache.keys().next().value;
        if (firstKey) {
          this.cache.delete(firstKey);
          authLogger.debug("Cache evicted old entry to make room", {
            evictedKey: firstKey,
          });
        }
      }

      // Store new entry
      this.cache.set(key, { data, timestamp: Date.now(), ttl });
      authLogger.debug("Data cached", {
        key,
        cacheSize: this.cache.size,
        maxSize: this.maxSize,
      });

      return data;
    } catch (error) {
      // Don't cache errors - let caller handle them
      authLogger.error("Error during cache fetch", {
        key,
        error: error instanceof Error ? error.message : "Unknown error",
      });
      throw error;
    }
  }

  /**
   * Invalidate cache entries matching a pattern
   * @param pattern - Pattern to match against keys (uses string.includes())
   *
   * @example
   * ```typescript
   * // Invalidate all student:123 caches
   * cache.invalidate('student:123');
   *
   * // Invalidate all teacher caches
   * cache.invalidate('teacher:');
   *
   * // Invalidate admin dashboard
   * cache.invalidate('admin:dashboard');
   * ```
   */
  invalidate(pattern: string): void {
    let invalidated = 0;
    for (const key of this.cache.keys()) {
      if (key.includes(pattern)) {
        this.cache.delete(key);
        invalidated++;
      }
    }
    authLogger.info("Cache invalidated", {
      pattern,
      entriesRemoved: invalidated,
    });
  }

  /**
   * Clear entire cache
   */
  clear(): void {
    const size = this.cache.size;
    this.cache.clear();
    this.metrics.hits = 0;
    this.metrics.misses = 0;
    authLogger.info("Cache cleared", { entriesRemoved: size });
  }

  /**
   * Get cache statistics for monitoring
   * @returns Cache metrics (size, utilization, hit rate)
   */
  getStats(): CacheMetrics {
    return {
      hits: this.metrics.hits,
      misses: this.metrics.misses,
      size: this.cache.size,
      maxSize: this.maxSize,
      utilizationPercent: (this.cache.size / this.maxSize) * 100,
    };
  }

  /**
   * Get hit ratio (percentage of cache hits)
   * @returns Hit ratio as percentage (0-100)
   */
  getHitRatio(): number {
    const total = this.metrics.hits + this.metrics.misses;
    return total === 0 ? 0 : (this.metrics.hits / total) * 100;
  }

  /**
   * Get all cached keys (for debugging)
   * @returns Array of cached keys
   */
  getKeys(): string[] {
    return Array.from(this.cache.keys());
  }

  /**
   * Get size of specific cache entry
   * @param key - Cache key
   * @returns Size in bytes (estimated) or 0 if not found
   */
  getEntrySize(key: string): number {
    const entry = this.cache.get(key);
    if (!entry) return 0;

    // Rough estimate: JSON.stringify byte length
    try {
      return JSON.stringify(entry.data).length;
    } catch {
      return 0;
    }
  }

  /**
   * Get estimated total cache size
   * @returns Total size in bytes (estimated)
   */
  getTotalSize(): number {
    let total = 0;
    for (const key of this.cache.keys()) {
      total += this.getEntrySize(key);
    }
    return total;
  }
}

/**
 * Global singleton instance of query cache
 * Safe to use across multiple requests (Map is thread-safe in Node.js)
 */
export const queryCache = new QueryCache();

/**
 * Connection Pool Monitor
 * Tracks Supabase connection pool utilization and alerts on high usage
 */

import { createClient } from "@supabase/supabase-js";
import type { SupabaseClient } from "@supabase/supabase-js";
import { authLogger } from "@/lib/auth-logger";
import type { Database } from "@/types/database";

export interface ConnectionPoolMetrics {
  activeConnections: number;
  maxConnections: number;
  utilizationPercent: number;
  timestamp: Date;
}

export interface PoolAlert {
  level: "warning" | "error" | "critical";
  message: string;
  metrics: ConnectionPoolMetrics;
  timestamp: Date;
}

/**
 * Connection Pool Monitor
 * Uses RPC function to query PostgreSQL connection stats
 */
export class ConnectionPoolMonitor {
  private supabase: SupabaseClient<Database>;
  private alerts: PoolAlert[] = [];
  private readonly maxAlerts = 100;
  private readonly warningThreshold = 70; // 70% utilization
  private readonly errorThreshold = 85; // 85% utilization
  private readonly criticalThreshold = 95; // 95% utilization
  private lastCheckTime = 0;
  private readonly minCheckInterval = 5000; // Check at most every 5 seconds

  constructor() {
    this.supabase = createClient<Database>(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: { autoRefreshToken: false, persistSession: false },
      },
    );
  }

  /**
   * Get current connection pool metrics
   */
  async getMetrics(): Promise<ConnectionPoolMetrics | null> {
    try {
      const now = Date.now();

      // Prevent excessive checks
      if (now - this.lastCheckTime < this.minCheckInterval) {
        return null;
      }

      this.lastCheckTime = now;

      // Try to get connection stats via RPC if function exists
      try {
        const { data, error } = await this.supabase.rpc(
          "get_connection_stats" as any,
          {},
        );

        if (error) {
          authLogger.debug("Connection stats RPC not available", {
            error: error.message,
          });
          return null;
        }

        if (data?.[0]) {
          const stats = data[0];
          return {
            activeConnections: stats.active_connections,
            maxConnections: stats.max_connections,
            utilizationPercent: stats.utilization_percent,
            timestamp: new Date(),
          };
        }
      } catch (rpcError) {
        authLogger.debug("Could not fetch connection stats via RPC", {
          rpcError,
        });
      }

      return null;
    } catch (error) {
      authLogger.error("Failed to get connection pool metrics", { error });
      return null;
    }
  }

  /**
   * Check connection pool health and alert if necessary
   */
  async checkHealth(): Promise<PoolAlert | null> {
    const metrics = await this.getMetrics();

    if (!metrics) {
      return null;
    }

    const utilization = metrics.utilizationPercent;
    let alert: PoolAlert | null = null;

    if (utilization >= this.criticalThreshold) {
      alert = {
        level: "critical",
        message: `CRITICAL: Connection pool at ${utilization.toFixed(1)}% capacity (${metrics.activeConnections}/${metrics.maxConnections} connections)`,
        metrics,
        timestamp: new Date(),
      };
      authLogger.error(alert.message);
    } else if (utilization >= this.errorThreshold) {
      alert = {
        level: "error",
        message: `ERROR: Connection pool at ${utilization.toFixed(1)}% capacity (${metrics.activeConnections}/${metrics.maxConnections} connections)`,
        metrics,
        timestamp: new Date(),
      };
      authLogger.warn(alert.message);
    } else if (utilization >= this.warningThreshold) {
      alert = {
        level: "warning",
        message: `WARNING: Connection pool at ${utilization.toFixed(1)}% capacity (${metrics.activeConnections}/${metrics.maxConnections} connections)`,
        metrics,
        timestamp: new Date(),
      };
      authLogger.warn(alert.message);
    }

    if (alert) {
      this.recordAlert(alert);
    }

    return alert;
  }

  /**
   * Record an alert in history
   */
  private recordAlert(alert: PoolAlert): void {
    this.alerts.push(alert);

    // Keep only recent alerts
    if (this.alerts.length > this.maxAlerts) {
      this.alerts = this.alerts.slice(-this.maxAlerts);
    }
  }

  /**
   * Get recent alerts
   */
  getRecentAlerts(limit: number = 10): PoolAlert[] {
    return this.alerts
      .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime())
      .slice(0, limit);
  }

  /**
   * Get alerts by level
   */
  getAlertsByLevel(level: "warning" | "error" | "critical"): PoolAlert[] {
    return this.alerts.filter((a) => a.level === level);
  }

  /**
   * Clear alert history
   */
  clearAlerts(): void {
    this.alerts = [];
  }
}

/**
 * Global connection pool monitor instance
 */
export const connectionPoolMonitor = new ConnectionPoolMonitor();

/**
 * Distributed Rate Limiter - Production-ready rate limiting with Redis support
 *
 * Implements token bucket algorithm for rate limiting auth operations
 * Supports both in-memory (development) and Redis (production) backends
 *
 * Features:
 * - Token bucket algorithm for fair rate limiting
 * - Redis support for distributed deployments
 * - Fallback to in-memory for development/outages
 * - Configurable limits and refill rates
 * - Admin operations (reset, clear)
 * - Monitoring and statistics
 * - Test environment detection (bypasses rate limiting in tests)
 * - Redis error tracking and metrics
 *
 * Error Handling:
 * - Production errors are tracked but not exposed in responses
 * - Redis fallback ensures service continuity during outages
 * - Error metrics available for monitoring/alerting
 *
 * Usage:
 * ```typescript
 * // Development (in-memory)
 * const limiter = new RateLimiter({ maxTokens: 5, refillRate: 5/3600 })
 *
 * // Production (Redis)
 * const limiter = new RateLimiter({ maxTokens: 5, refillRate: 5/3600 }, redisClient)
 * ```
 */

import { authLogger } from "./auth-logger";

/**
 * Detect if we're running in test environment
 * Matches test detection in button.tsx for consistency
 */
function isTestEnvironment(): boolean {
  if (typeof process === "undefined") return false;

  return (
    process.env.NODE_ENV === "test" ||
    process.env.PLAYWRIGHT_TEST === "true" ||
    process.env.CI === "true"
  );
}

interface RateLimitEntry {
  tokens: number;
  lastRefill: number;
}

/**
 * Redis client interface - supports redis, ioredis, and other compatible clients
 * Defines the minimum required methods for rate limiting operations
 */
interface RedisClient {
  get(key: string): Promise<string | null>;
  set(
    key: string,
    value: string,
    options?: { EX?: number; ex?: number },
  ): Promise<void | "OK">;
  setex(key: string, seconds: number, value: string): Promise<void | "OK">;
  del(...keys: string[]): Promise<number>;
  keys(pattern: string): Promise<string[]>;
  incr(key: string): Promise<number>;
  expire(key: string, seconds: number): Promise<number>;
  ttl(key: string): Promise<number>;
  flushdb(): Promise<void | "OK">;
}

interface RateLimitConfig {
  maxTokens: number; // Maximum tokens in bucket
  refillRate: number; // Tokens per second (e.g., 1 token per 600 seconds = 6 per hour)
  refillInterval: number; // Refill check interval in milliseconds
  ttl?: number; // TTL in seconds for Redis keys (default: 3600)
}

interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // Seconds until next request allowed
}

/**
 * Base rate limiter interface for both in-memory and Redis implementations
 */
interface IRateLimiter {
  isAllowed(key: string): Promise<boolean>;
  getRemaining(key: string): Promise<number>;
  reset(key: string): Promise<void>;
  clearAll(): Promise<void>;
  getSize(): Promise<number>;
  getStatus(key: string): Promise<RateLimitEntry | null>;
}

/**
 * In-memory rate limiter (development)
 * WARNING: Not suitable for production with multiple server instances
 */
class InMemoryRateLimiter implements IRateLimiter {
  private store: Map<string, RateLimitEntry> = new Map();
  private config: RateLimitConfig;
  // MEDIUM #5 Fix: TTL-based cleanup for fallback limiter
  // Entries older than TTL are automatically removed to prevent memory leaks
  private readonly ENTRY_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours
  private readonly CLEANUP_INTERVAL_MS = 60 * 60 * 1000; // Clean up every hour
  private cleanupTimer?: NodeJS.Timeout;

  constructor(config: RateLimitConfig) {
    this.config = config;
    this.startCleanupTimer();
  }

  /**
   * Start periodic cleanup of expired entries (MEDIUM #5 fix)
   * Prevents memory accumulation when Redis is unavailable
   */
  private startCleanupTimer(): void {
    if (typeof setInterval === "undefined") {
      // Skip timer in non-Node environments (e.g., browsers)
      return;
    }

    this.cleanupTimer = setInterval(() => {
      this.cleanupExpiredEntries();
    }, this.CLEANUP_INTERVAL_MS);

    // Allow timer to be garbage collected if process exits
    if (this.cleanupTimer.unref) {
      this.cleanupTimer.unref();
    }
  }

  /**
   * Remove entries that haven't been updated in TTL period
   * Called periodically by cleanup timer
   */
  private cleanupExpiredEntries(): void {
    const now = Date.now();
    let removedCount = 0;

    for (const [key, entry] of this.store.entries()) {
      // Remove if not updated in ENTRY_TTL_MS
      if (now - entry.lastRefill > this.ENTRY_TTL_MS) {
        this.store.delete(key);
        removedCount++;
      }
    }

    if (removedCount > 0) {
      authLogger.debug("[InMemoryRateLimiter] Cleaned up expired entries", {
        removedCount,
      });
    }
  }

  async isAllowed(key: string): Promise<boolean> {
    // IMPORTANT: Bypass rate limiting in test environment
    // Tests should verify functionality, not rate limiting behavior
    // Rate limiting is an operational concern tested separately
    if (isTestEnvironment()) {
      return true;
    }

    const now = Date.now();
    const entry = this.store.get(key);

    // Initialize new entry if doesn't exist
    if (!entry) {
      this.store.set(key, {
        tokens: this.config.maxTokens - 1,
        lastRefill: now,
      });
      return true;
    }

    // Calculate tokens to add based on time elapsed
    const timePassed = (now - entry.lastRefill) / 1000;
    const tokensToAdd = timePassed * this.config.refillRate;

    // Update tokens and last refill time
    entry.tokens = Math.min(this.config.maxTokens, entry.tokens + tokensToAdd);
    entry.lastRefill = now;

    // Check if we have tokens available
    if (entry.tokens >= 1) {
      entry.tokens -= 1;
      return true;
    }

    return false;
  }

  async getRemaining(key: string): Promise<number> {
    const entry = this.store.get(key);
    if (!entry) return this.config.maxTokens;
    return Math.floor(entry.tokens);
  }

  async reset(key: string): Promise<void> {
    this.store.delete(key);
  }

  async clearAll(): Promise<void> {
    this.store.clear();
  }

  async getSize(): Promise<number> {
    return this.store.size;
  }

  async getStatus(key: string): Promise<RateLimitEntry | null> {
    return this.store.get(key) || null;
  }
}

/**
 * Redis-backed rate limiter (production)
 * Supports distributed rate limiting across multiple server instances
 * Falls back to in-memory limiter if Redis is unavailable
 */
class RedisRateLimiter implements IRateLimiter {
  private redisClient: RedisClient;
  private config: RateLimitConfig;
  private prefix: string;
  private fallbackLimiter: InMemoryRateLimiter;
  private redisAvailable: boolean = true;

  // Lua script for atomic rate limit check-and-update (prevents TOCTOU race condition)
  // This script is atomic at the Redis level, ensuring no concurrent requests can bypass limits
  private rateLimitScript = `
    local key = KEYS[1]
    local now = tonumber(ARGV[1])
    local max_tokens = tonumber(ARGV[2])
    local refill_rate = tonumber(ARGV[3])
    local ttl = tonumber(ARGV[4])

    local data = redis.call('GET', key)
    local entry

    if not data then
      -- Initialize new entry with one token already consumed
      entry = {tokens = max_tokens - 1, lastRefill = now}
      redis.call('SETEX', key, ttl, cjson.encode(entry))
      return 1  -- Allowed
    end

    -- Parse existing entry
    entry = cjson.decode(data)

    -- Calculate tokens to add based on time elapsed
    local time_passed = (now - entry.lastRefill) / 1000
    local tokens_to_add = time_passed * refill_rate

    -- Update tokens (cap at max_tokens)
    entry.tokens = math.min(max_tokens, entry.tokens + tokens_to_add)
    entry.lastRefill = now

    -- Check if we have tokens available
    if entry.tokens >= 1 then
      entry.tokens = entry.tokens - 1
      redis.call('SETEX', key, ttl, cjson.encode(entry))
      return 1  -- Allowed
    end

    -- Rate limited - update expiry
    redis.call('EXPIRE', key, ttl)
    return 0  -- Not allowed
  `;

  constructor(
    config: RateLimitConfig,
    redisClient: RedisClient,
    prefix: string = "ratelimit:",
  ) {
    this.config = config;
    this.redisClient = redisClient;
    this.prefix = prefix;
    // Create fallback in-memory limiter for when Redis is unavailable
    this.fallbackLimiter = new InMemoryRateLimiter(config);
  }

  private getRedisKey(key: string): string {
    return `${this.prefix}${key}`;
  }

  async isAllowed(key: string): Promise<boolean> {
    // IMPORTANT: Bypass rate limiting in test environment
    // Tests should verify functionality, not rate limiting behavior
    // Rate limiting is an operational concern tested separately
    if (isTestEnvironment()) {
      return true;
    }

    // If Redis is already known to be unavailable, use fallback immediately
    if (!this.redisAvailable) {
      return this.fallbackLimiter.isAllowed(key);
    }

    const redisKey = this.getRedisKey(key);
    const now = Date.now();

    try {
      // Use Lua script for atomic check-and-update to prevent TOCTOU race condition
      // SECURITY: This ensures only one request can decrement the token count per check
      // The script is executed atomically on the Redis server
      const ttl = this.config.ttl || 3600;

      // EVAL executes the Lua script atomically
      // Returns 1 if allowed, 0 if rate limited
      const result = await (this.redisClient as any).eval(
        this.rateLimitScript,
        1, // number of keys
        redisKey, // KEYS[1]
        now.toString(), // ARGV[1]
        this.config.maxTokens.toString(), // ARGV[2]
        this.config.refillRate.toString(), // ARGV[3]
        ttl.toString(), // ARGV[4]
      );

      return result === 1;
    } catch (_error) {
      // If Lua script fails (e.g., Redis version < 2.6), fallback to non-atomic approach
      // This is acceptable as it degrades gracefully
      try {
        // Attempt non-atomic fallback (vulnerable to race conditions but better than failing)
        const data = await this.redisClient.get(redisKey);
        let entry: RateLimitEntry;

        if (!data) {
          entry = {
            tokens: this.config.maxTokens - 1,
            lastRefill: now,
          };
        } else {
          entry = JSON.parse(data);
          const timePassed = (now - entry.lastRefill) / 1000;
          const tokensToAdd = timePassed * this.config.refillRate;
          entry.tokens = Math.min(
            this.config.maxTokens,
            entry.tokens + tokensToAdd,
          );
          entry.lastRefill = now;
        }

        if (entry.tokens >= 1) {
          entry.tokens -= 1;
          const ttl = this.config.ttl || 3600;
          await this.redisClient.setex(redisKey, ttl, JSON.stringify(entry));
          return true;
        }

        const ttl = this.config.ttl || 3600;
        await this.redisClient.expire(redisKey, ttl);
        return false;
      } catch (fallbackError) {
        // FALLBACK: Use in-memory rate limiter if Redis fails
        this.redisAvailable = false;
        if (process.env.NODE_ENV === "development") {
          authLogger.error(
            "[RedisRateLimiter] Redis unavailable - falling back to in-memory",
            { error: fallbackError },
          );
        }
        return this.fallbackLimiter.isAllowed(key);
      }
    }
  }

  async getRemaining(key: string): Promise<number> {
    // Use fallback if Redis is unavailable
    if (!this.redisAvailable) {
      return this.fallbackLimiter.getRemaining(key);
    }

    const redisKey = this.getRedisKey(key);

    try {
      const data = await this.redisClient.get(redisKey);
      if (!data) return this.config.maxTokens;

      const entry: RateLimitEntry = JSON.parse(data);
      return Math.floor(entry.tokens);
    } catch (_error) {
      // Mark Redis as unavailable and use fallback
      this.redisAvailable = false;
      return this.fallbackLimiter.getRemaining(key);
    }
  }

  async reset(key: string): Promise<void> {
    // Reset in fallback as well
    await this.fallbackLimiter.reset(key);

    // Try to reset in Redis if available
    if (!this.redisAvailable) return;

    const redisKey = this.getRedisKey(key);

    try {
      await this.redisClient.del(redisKey);
    } catch (_error) {
      // Mark Redis as unavailable
      this.redisAvailable = false;
    }
  }

  async clearAll(): Promise<void> {
    // Clear fallback
    await this.fallbackLimiter.clearAll();

    // Try to clear Redis if available
    if (!this.redisAvailable) return;

    try {
      const pattern = `${this.prefix}*`;
      const keys = await this.redisClient.keys(pattern);

      if (keys.length > 0) {
        await this.redisClient.del(...keys);
      }
    } catch (_error) {
      // Mark Redis as unavailable
      this.redisAvailable = false;
    }
  }

  async getSize(): Promise<number> {
    // If Redis unavailable, return fallback size
    if (!this.redisAvailable) {
      return this.fallbackLimiter.getSize();
    }

    try {
      const pattern = `${this.prefix}*`;
      const keys = await this.redisClient.keys(pattern);
      return keys.length;
    } catch (_error) {
      // Mark Redis as unavailable and use fallback
      this.redisAvailable = false;
      return this.fallbackLimiter.getSize();
    }
  }

  async getStatus(key: string): Promise<RateLimitEntry | null> {
    // Use fallback if Redis unavailable
    if (!this.redisAvailable) {
      return this.fallbackLimiter.getStatus(key);
    }

    const redisKey = this.getRedisKey(key);

    try {
      const data = await this.redisClient.get(redisKey);
      if (!data) return null;
      return JSON.parse(data);
    } catch (_error) {
      // Mark Redis as unavailable and use fallback
      this.redisAvailable = false;
      return this.fallbackLimiter.getStatus(key);
    }
  }
}

/**
 * Factory function to create appropriate rate limiter
 * Uses Redis if available, falls back to in-memory
 */
export function createRateLimiter(
  config: RateLimitConfig,
  redisClient?: RedisClient,
): IRateLimiter {
  if (redisClient) {
    return new RedisRateLimiter(config, redisClient);
  }
  return new InMemoryRateLimiter(config);
}

/**
 * High-level API for rate limiting
 * Provides convenient interface for common operations
 */
export class RateLimitManager {
  private limiters: Map<string, IRateLimiter> = new Map();
  private redisClient?: RedisClient;

  constructor(redisClient?: RedisClient) {
    this.redisClient = redisClient;
  }

  private getOrCreateLimiter(
    name: string,
    config: RateLimitConfig,
  ): IRateLimiter {
    if (!this.limiters.has(name)) {
      this.limiters.set(name, createRateLimiter(config, this.redisClient));
    }
    const limiter = this.limiters.get(name);
    if (!limiter) {
      throw new Error(`Rate limiter "${name}" not found after creation`);
    }
    return limiter;
  }

  /**
   * Check if a request is allowed and return detailed result
   */
  async checkLimit(
    limiterName: string,
    key: string,
    config: RateLimitConfig,
  ): Promise<RateLimitResult> {
    const limiter = this.getOrCreateLimiter(limiterName, config);
    const allowed = await limiter.isAllowed(key);
    const remaining = await limiter.getRemaining(key);

    return {
      allowed,
      remaining,
      retryAfter: allowed ? undefined : Math.ceil(1 / config.refillRate),
    };
  }

  /**
   * Get remaining quota for a key
   */
  async getRemaining(
    limiterName: string,
    key: string,
    config: RateLimitConfig,
  ): Promise<number> {
    const limiter = this.getOrCreateLimiter(limiterName, config);
    return limiter.getRemaining(key);
  }

  /**
   * Reset rate limit for a key
   */
  async reset(
    limiterName: string,
    key: string,
    config: RateLimitConfig,
  ): Promise<void> {
    const limiter = this.getOrCreateLimiter(limiterName, config);
    return limiter.reset(key);
  }

  /**
   * Get detailed status for debugging
   */
  async getStats(): Promise<
    Record<string, { entries: number; limiter: string }>
  > {
    const stats: Record<string, { entries: number; limiter: string }> = {};

    for (const [name, limiter] of this.limiters) {
      stats[name] = {
        entries: await limiter.getSize(),
        limiter: this.redisClient ? "Redis" : "In-Memory",
      };
    }

    return stats;
  }
}

/**
 * Export singleton instance
 * Can be replaced with Redis-backed instance in production
 */
export const defaultRateLimitManager = new RateLimitManager();

/**
 * Convenience functions for backward compatibility
 */
export async function checkRateLimit(
  key: string,
  config: RateLimitConfig,
): Promise<boolean> {
  const result = await defaultRateLimitManager.checkLimit(
    "default",
    key,
    config,
  );
  return result.allowed;
}

export async function getRateLimitStatus(
  key: string,
  config: RateLimitConfig,
): Promise<RateLimitResult> {
  return defaultRateLimitManager.checkLimit("default", key, config);
}

export async function resetRateLimit(
  key: string,
  config: RateLimitConfig,
): Promise<void> {
  return defaultRateLimitManager.reset("default", key, config);
}

